(7, 'বিপিএল', 'No', 'No', 'চট্টগ্রামকে হেসে-খেলেই হারাল সিলেট', NULL, 'বাংলাদেশ প্রিমিয়ার লিগ (বিপিএল) এর প্রথম ম্যাচে তারুণ্যনির্ভর চট্টগ্রামকে পাত্তাই দেয়নি মাশরাফি-মুশফিকের অভিজ্ঞ খুলনা দল। ব্যাট ও বল হাতে রীতিমতো', NULL, '116371777_2736191056657982_4018997381434909915_n1673040361.jpg', '3', 'খেলা', 'No', '2023-01-07', '2023-01-16', '07:53PM', NULL, 1, 1, NULL, '2023-01-07 03:26:00am', '2023-01-16 19:53:37', NULL, 'চট্টগ্রাম', 'চট্টগ্রাম', 'সীতাকুন্ড', 'সেজান মাহমুদ', NULL, '1673040240', 'Noman Abdullah'),
(8, 'বিপিএল', 'Yes', 'No', 'শীতের ঠেলায় বাঁচতে পারছি নাহ', NULL, 'শীতের ঠেলায় বাঁচতে পারছি নাহ&nbsp;শীতের ঠেলায় বাঁচতে পারছি নাহ&nbsp;শীতের ঠেলায় বাঁচতে পারছি নাহ&nbsp;শীতের ঠেলায় বাঁচতে পারছি নাহ', NULL, 'cMDRA3454bGvfZASbxviZe1673188690.jpg', '6', 'জাতীয়', 'No', '2023-01-08', '2023-01-08', '11:54PM', NULL, 1, 1, NULL, '2023-01-08 08:38:09pm', '2023-01-08 23:54:16', NULL, 'Barishal', 'Bhola', 'Bhola Sadar', 'সেজান মাহমুদ', NULL, '1673188560', 'Noman Abdullah'),
(9, 'মেট্রোরেল', 'Yes', 'No', '১০ দিনে মেট্রোরেলের আয় ৮৮ লাখ টাকা', NULL, 'সোমবার (৯ জানুয়ারি) দুপুরে রাজধানীর পুরাতন এলিফ্যান্ট রোডে ডিএমটিসিএলের সভা কক্ষে এ তথ্য জানান প্রতিষ্ঠানটির ব্যবস্থাপনা পরিচালক এম এ এন ছিদ্দিক। তিনি বলেন, গত ২৯ ডিসেম্বর থেকে ৮ জানুয়ারি পর্যন্ত ১০ দিনে ৯০ হাজার যাত্রী&nbsp;মেট্রোরেলে চলাচল&nbsp;করেছে। তাদের মধ্যে সিঙ্গেল জার্নি টিকিট বিক্রি হয়েছে ৮৩ হাজার। আর এমআরটি পাস বিক্রি হয়েছে ৭ হাজার ২৫০টি। এসব টিকিট বিক্রি থেকে মোট ৮৮ লাখ টাকা আয় হয়েছে।এর আগে, গত বছরের ২৮ ডিসেম্বর মেট্রোরেলের উদ্বোধন করেন প্রধানমন্ত্রী শেখ হাসিনা। পরদিন ২৯ ডিসেম্বর বাণিজ্যিকভাবে যাত্রা শুরু করে মেট্রোরেল। তখন থেকে উত্তরা উত্তর (দিয়াবাড়ী) থেকে আগারগাঁও পর্যন্ত সরাসরি চলাচল করছে মেট্রোরেল।', NULL, 'pl-202301091600351673376559.jpg', '1', 'জাতীয়', 'Yes', '2023-01-11', '2023-01-11', '12:40AM', NULL, 1, NULL, NULL, '2023-01-11 12:49:18am', NULL, NULL, 'ঢাকা', 'ঢাকা', 'অন্যান্য', 'জামান আব্দুল্লাহ', NULL, '1673376000', 'Noman Abdullah'),
(10, 'বিশ্ব ইজতেমা', 'Yes', 'No', 'বিশ্ব ইজতেমায় থাকছে ৫ জোড়া বিশেষ ট্রেন ', NULL, 'ইজতেমার প্রথম পর্বে শুক্রবার (১৩ জানুয়ারি) থেকে আখেরি মোনাজাত ও দ্বিতীয় পর্বে ২০ জানুয়ারি আখেরি মোনাজাত পর্যন্ত বিভিন্ন গন্তব্যে এসব সেবা চালু হবে। বিজ্ঞপ্তিতে বলা হয়েছে, টঙ্গীতে আসন্ন বিশ্ব ইজতেমায় অংশগ্রণকারী মুসুল্লীদের যাতায়াতের সুবিধার্থে বাংলাদেশ রেলওয়ে বিভিন্ন রুটে বিশেষ ট্রেন চলাচলের ব্যবস্থা গ্রহণ করেছে। দুই পর্বের আখেরি মোনাজাতের আগে ও মোনাজাতের দিন এই বিশেষ ট্রেন পরিচালিত হবে।এর মধ্যে প্রথম পর্বের ইজতেমায় শুক্রবার ও দ্বিতীয় পর্বের শুক্রবার ঢাকা-টঙ্গী ও টঙ্গী-ঢাকা রুটে জুমা স্পেশাল পরিচালিত হবে। যা ঢাকা থেকে সকাল ১০টা ২০ মিনিটে ছেড়ে বেলা ১১টা ২০ মিনিটে টঙ্গী পৌঁছবে। একইভাবে দুপুর ২টা ৫০ মিনিটে টঙ্গী থেকে ছেড়ে বেলা ৩টা ৫০ মিনিটে ঢাকা পৌঁছবে। এছাড়াও ১৪ জানুয়ারি ও ২১ জানুয়ারি জামালপুর থেকে টঙ্গীর উদ্দেশ্যে বিশেষ ট্রেন চলবে। যা সকাল ৯টা ১৫ মিনিটে জামালপুর থেকে টঙ্গীর উদ্দেশ্যে ছেড়ে এসে দুপুর ২টা ১৫ মিনিটে পৌঁছবে।আখেরি মোনাজাতের দিন (১৫ জানুয়ারি ও ২২ জানুয়ারি) বিশেষ ট্রেন ঢাকা-টঙ্গী স্পেশাল-১, ২, ৩, ৪, ৫ নামে পাঁচটি স্পেশাল ট্রেন ঢাকা-টঙ্গীর মধ্যে চলাচল করবে। এছাড়াও টঙ্গী-ময়মনসিংহ ১, ২ ও টঙ্গী-টাঙ্গাইল স্পেশাল নামের আরও দুটি ট্রেন চলাচল করবে। এদিকে প্রথম পর্বে ১৩ জানুয়ারি থেকে ১৫ জানুয়ারি এবং দ্বিতীয় পর্বে ২০ জানুয়ারি থেকে ২২ জানুয়ারি পর্যন্ত আখেরি মোনাজাতের দিন ঢাকা অভিমুখী সকল আন্তঃনগর মেইল এক্সপ্রেস ও কমিউটার ট্রেন টঙ্গী স্টেশনে তিন মিনিট করে থামবে। ১৫ ও ২২ জানুয়ারি আখেরি মোনাজাতের দিন সুবর্ণ এক্সপ্রেস ও সোনারবাংলা এক্সপ্রেস ব্যতীত সকল আন্তঃনগর ট্রেন ও মেইল এক্সপ্রেস ট্রেন আপ-ডাউন টঙ্গী স্টেশনে তিন মিনিট করে থামবে। এছাড়াও আখেরি মোনাজাতের পরের দিন ১৬ জানুয়ারি ও ২৩ জানুয়ারি ইজতেমা হতে বর্হিগামী টিকেটধারী যাত্রীদের ফেরত যাওয়া ও টঙ্গী স্টেশনে আরোহনের সুবিধার্থে ৭০৪, ৭০৫, ৭০৭, ৭১৭, ৭২২, ৭২৬, ৭৩৫, ৭৩৭, ৭৩৯, ৭৪৫, ৭৫১, ৭৫৩, ৭৫৭, ৭৬৪, ৭৬৫, ৭৬৯, ৭৭১, ৭৭৩, ৭৭৬, ৭৭৭, ৭৮১, ৭৮৯, ৭৯৬ ও ৭৯৭ নং ট্রেন টঙ্গী স্টেশনে তিন মিনিট থামবে।আখেরি মোনাজাতের দিন ১৫ ও ২২ জানুয়ারি তুরাগ-১, ২, ৩ ও ৪ ট্রেন চলাচল করবে না ও ৪৯নং বলাকা কমিউটার ট্রেন ঢাকা হতে ৪টা ৪০ মিনিটের পরিবর্তে ৫টা ২৫ মিনিটে এবং ৪নং কর্ণফুলী কমিউটার ট্রেন আখেরি মোনাজাতের দিন সকাল ৮টা ৩০ মিনিটের পরিবর্তে দুপুর ১২টা এবং ৩৪নং তিতাস কমিউটার ৯টা ৪৫ মিনিটের পরিবর্তে দুপুর ১২টা ৩০ মিনিটে ঢাকা হতে ছেড়ে যাবে। ১৫ ও ২২ জানুয়ারি ৭০১/৭৩২নং সুবর্ণ এক্সপ্রেস বন্ধ থাকবে, ১৬ ও ২৩ জানুয়ারি সোমবার ৭০১/৭০২নং সুবর্ণ এক্সপ্রেস ট্রেন সাপ্তাহিক বন্ধের দিন চলাচল করবে, ৭৫/৭৬নং ধলেশ্বরী এক্সপ্রেস ট্রেন ২৬১-২৬৪ নং লোকার ট্রেন ১৪ ও ১৫ জানুয়ারি এবং ২১ ও ২২ জানুয়ারি তারিখে চলাচল করবে, ১৪ ও ২১ জানুয়ারি ১০ ডাউন সিলেট থেকে ১১ ডাউন নোয়াখালী থেকে, ৫৬নং ট্রেন দেওয়ানগঞ্জ থেকে টাঙ্গাইল কমিউটার বঙ্গবন্ধু সেতু পূর্ব থেকে ওপেন পাথে ইজতেমা স্পেশাল ট্রেনের কার্যক্রম পরিচালনার জন্য ঢাকায় থাকবে বলে জানানো হয়েছে।বাংলাদেশ রেওয়ে পূর্বাঞ্চলের চিফ অপারেটিং সুপারিনটেনডেন্ট (পূর্ব) মো. শহিদুল ইসলাম জানান, ইজতেমার দুই পর্বে ঢাকা থেকে পাঁচ জোড়া স্পেশাল ট্রেন চলবে। এছাড়াও জামালপুর থেকে স্পেশাল ট্রেন চলবে এবং ময়মনসিংহে আখেরি মোনাজাতের দিন দুইটি স্পেশাল ট্রেন যাবে। ইজতেমায় আগত মুসুল্লীদের যাতায়াত নির্বিঘ্ন করতে এ সিদ্ধান্ত নেওয়া হয়েছে। পাশাপাশি বিশ্ব ইজতেমা উপলক্ষে মুসল্লিদের নিরাপদ ভ্রমণ নিশ্চিতকরণ, সার্বিক আইনশৃঙ্খলা রক্ষার্থে টঙ্গী, বিমানবন্দর, তেজগাঁও, কমলাপুর, টঙ্গী রেলওয়ে স্টেশনে জিআরপি, আরএনবি অফিসারসহ প্রয়োজনীয় সংখ্যক ফোর্স মোতায়েন থাকবে।', NULL, 'untitled-6-202301101305181673377388.jpg', '2', 'জাতীয়', 'Yes', '2023-01-11', '2023-01-11', '12:58AM', NULL, 1, NULL, NULL, '2023-01-11 01:03:07am', NULL, NULL, 'ঢাকা', 'গাজীপুর', 'গাজীপুর সদর', 'সেজান মাহমুদ', NULL, '1673377080', 'Noman Abdullah'),
(11, ' আবহাওয়ার খবর', 'Yes', 'Yes', 'দেখা মিলেছে সূর্যের, কাজে ফিরছেন শ্রমজীবীরা', NULL, '<p><strong>গেল সপ্তাহ থেকে উত্তরাঞ্চলের বেশিরভাগ জেলায় দেখা মেলেনি সূর্যের। এছাড়া গুঁড়ি গুঁড়ি বৃষ্টির মতো ঝরেছে কুয়াশা। এই হাড় কাঁপানো ঠান্ডায় কাজে যেতে না পেরে মানবেতর জীবনযাপন কেটেছে সাধারণ মানুষদের। তবে দীর্ঘ সময় পর মঙ্গলবার (১০ জানুয়ারি) সূর্যের দেখা মিলেছে লালমনিরহাটে। তাই কর্মজীবী মানুষরাও আবার কাজে ফিরছেন। কাজে ফিরতে পেরে অনেক খুশি তারা।</strong></p><p><strong></strong>মঙ্গলবার সকালে আবহাওয়া পর্যবেক্ষণ কেন্দ্রের তুহিন আহমেদ জানিয়েছেন, লালমনিরহাট ও কড়িগ্ৰাম রাজারহাটে আজ ৮ দশমিক ২ ডিগ্রি সেলসিয়াস রেকর্ড করা হয়েছে। তাপমাত্রা বৃদ্ধি হওয়ার কারণে এই লালমনিরহাটের পাঁচ উপজেলায় সূর্যের দেখা মিলেছে। সূর্যের দেখা পাওয়ায় কর্মে ফিরেছেন সকল মানুষ। যদিও ঠান্ডা হাওয়া এখনো কমেনি। বিশেষ করে ভোগান্তিতে পড়েছেন তিস্তা চর অঞ্চলের মানুষরা। শীতে সবচেয়ে বেশি দুর্ভোগে রয়েছে লালমনিরহাটের ১৩টি নদ-নদীর তীরবর্তী ৬৩টি চরের প্রায় ৫০ হাজার মানুষসহ নিম্ন আয়ের শ্রমজীবীরা। গবাদি পশুও রেহাই পাচ্ছে না শীতের প্রকোপ থেকে।এছাড়াও ঠাণ্ডার সঙ্গে পাল্লা দিয়ে বেড়েছে শীতজনিত নানা রোগ। গত এক সপ্তাহে ডায়রিয়া, নিউমোনিয়া, হাঁপানি, অ্যাজমা, হৃদরোগসহ নানা রোগে আক্রান্ত হয়ে লালমনিরহাট সদর হাসপাতালসহ উপজেলা স্বাস্থ্য কমপ্লেক্সগুলোতে ভর্তি হচ্ছে ঠান্ডাজনিত রোগীরা।&nbsp;তিস্তা অঞ্চলের মোহাম্মদ আলী বলেন, প্রায় ১০ দিন থেকে বাইরে কাজে যেতে পারিনি। যে কারণে আমি ও আমার পরিবারকে নিয়ে অনেক কষ্টে ছিলাম। প্রচন্ড শীতের কেউ আমাকে কম্বল দেয়নি। সন্তানদের গরম কাপড় কিনে দিতে গবাদি পশু বিক্রি করতে হয়েছে। এই অবস্থায় থাকলে অন্তত মানুষ না খেয়ে মরে যাবে।&nbsp; ঠান্ডায় কাবু হয়ে রমিছা বেগম বলেন, অনেকদিন পর সূর্যের দেখা পেয়েছি, সূর্যের গরম তাপ নিয়ে কাজে ফিরেছি। দিনমজুরের কাজ না করলে সংসার চালাবো কীভাবে। এই শীতে আমাদের কাজকর্ম করেই চলতে হবে।&nbsp;লালমনিরহাট জেলা প্রশাসক মোহাম্মদ উল্যাহ জানান, মানুষের পাশে সব সময় জেলা প্রশাসন আছে। জেলায় শীতার্ত ও অসহায় মানুষের মাঝে ইতোমধ্যে ২৫ হাজার কম্বল বিতরণ করা হয়েছে। জেলার পাঁচ উপজেলার নির্বাহী অফিসারদের মাধ্যমে সরকারি কম্বল বিতরণের পাশাপাশি বিভিন্ন বেসরকারি সংস্থা শীতবস্ত্র বিতরণ অব্যাহত রেখেছেন। এই শীতে কম্বল বিতরণসহ শীতের বিভিন্ন উপকরণ নিয়ে জেলা প্রশাসক মানুষের পাশে থাকবে।</p>', NULL, 'untitled-3-202301101108231673381358.jpg', '6', 'জাতীয়', 'Yes', '2023-01-11', '2023-01-11', '02:06AM', NULL, 1, NULL, NULL, '2023-01-11 02:09:17am', NULL, NULL, 'ঢাকা', '', NULL, 'সেজান মাহমুদ', NULL, '1673381160', 'Noman Abdullah'),
(12, 'আবহাওয়ার খবর', 'Yes', 'Yes', 'পঞ্চগড়ের তাপমাত্রা ৬.৯ ডিগ্রি', NULL, 'সকালে সূর্যের দেখা মিললেও এখনও কনকনে শীতে কাঁপছে পঞ্চগড়। মঙ্গলবার (১০ জানুয়ারি) সকাল ৯টায় এ জেলায় তাপমাত্রা রেকর্ড হয়েছে ৬ দশমিক ৯ ডিগ্রি সেলসিয়াস। তাপমাত্রা গতকাল থেকে কমেছে শূন্য দশমিক ১ ডিগ্রি সেলসিয়াস। গতকাল সোমবার তাপমাত্রা রেকর্ড হয়েছিল ৭ ডিগ্রি সেলসিয়াস। দুদিন ধরে মাঝারি শৈত্যপ্রবাহের দাপটে বিপর্যস্ত হয়ে পড়েছে উত্তরের এ জনপদে।আবহাওয়া অধিদপ্তর জানায়, দুদিন ধরে সর্বনিম্ন তাপমাত্রা রেকর্ড হওয়ায় এ জেলায় মাঝারি শৈত্যপ্রবাহ বইছে। গত শুক্রবার থেকে রোববার পর্যন্ত তাপমাত্রা ৯.৬, ৯.৫ ও ৯.৪ ডিগ্রি সেলসিয়াস রেকর্ড হয়েছিল। সোমবার তাপমাত্রা কমে ৭ ডিগ্রিতে পৌঁছেছে। মঙ্গলবার সকাল থেকে তাপমাত্রা শূন্য দশমিক ১ ডিগ্রি কমে ৬ দশমিক ৯ ডিগ্রি সেলসিয়াস রেকর্ড হয়েছে। সকালে দেশের সর্বনিম্ন তাপমাত্রা রেকর্ড হওয়ার বিষয়টি ঢাকা পোস্টকে জানিয়েছেন জেলার প্রথম শ্রেণির আবহাওয়া অধিদপ্তরের ভারপ্রাপ্ত কর্মকর্তা রাসেল শাহ। এর আগে, এই জেলায় ২০১৮ সালের জানুয়ারিতে স্মরণকালের সবচেয়ে কম ২ দশমিক ৬ ডিগ্রি সেলসিয়াস তাপমাত্রা রেকর্ড হয়েছিল।&nbsp;সকাল থেকেই দেখা মিলেছে সূর্যের। তবে অনুভূত হচ্ছে প্রচন্ড শীত। সুর্যের মুখ দেখা গেলেও মিলছে না রোদের উষ্ণতা। শীত দুর্ভোগে পড়েছে নানান শ্রমজীবী-কর্মজীবী গরিব অসহায় মানুষ। পাথর শ্রমিক, চা শ্রমিক, দিনমজুর থেকে শুরু করে ছোটখাটো যানবাহন ভ্যান চালক মানুষগুলো পড়েছেন বিপাকে। তীব্র শীতের কারণে কাজে যেতে পারছেন না অনেকে। তবে জীবিকার তাগিদে কাউকে নদীতে পাথর তুলতে, কাউকে চা-বাগানে আবার কাউকে দিনমজুরের কাজ করতে যেতে দেখা গেছে। শীতের দুর্ভোগ বেড়েছে শিশু ও বয়স্কদের মধ্যে। এসব মানুষের কষ্ট লাঘবের জন্য সরকার যে ত্রাণ দিয়েছে তা একেবারে অপ্রতুল বলে জানিয়েছেন ভুক্তভোগীরা। চা শ্রমিক জামাল, জাহেরুল ও নাসির জানান, সকালে বরফের মতো ঠান্ডা। চা বাগানে কাজ করতে গেলে হাত-পা অবশ হয়ে আসে। কিন্তু জীবিকার তাগিদে কাজে বের হতে হয় আমাদের।পাথর শ্রমিক ইমরান, আরশাদ আলী ও আবু তাহের জানান, ঠান্ডায় নদীর পানি বরফের মতো মনে হয়। তারপরেও আমাদের পাথরই জীবিকা। তাই কাজে বেড়িয়েছি। কয়েকদিন ধরে নদীর ঠান্ডা পানিতে কাজ করে জ্বর-সর্দিতে ভুগলাম। ক্ষুধার্ত পেটতো ঠান্ডা বুঝে না। কিন্তু পরিবারের কথা চিন্তা করে সকালেই পাথর তোলার সরঞ্জাম নিয়ে বেড়িয়ে পড়েছি। একই কথা জানান কয়েকজন দিনমজুর ও নারী পাথর শ্রমিকরা।আরও পড়ুন &gt;&gt;&gt;&nbsp;শীতে স্বাস্থ্য সুরক্ষায় করণীয়নারী পাথর শ্রমিকরা জানান, তীব্র শীতের কারণে তাদেরও কাজে যেতে কষ্ট হচ্ছে। ঘর সংসার সামলে জীবিকার তাগিদে কাজে যেতে হচ্ছে। শীতের কারণে কাজে যেতে দেরি হলে মহাজনরা অনেক সময় কাজে নিতে চান না।বীজতলা নিয়ে বিপাকে পড়েছেন কৃষকরাও। তারা জানান, ঘন কুয়াশা আর কনকনে শীতের কারণে ক্ষেতখামারে কাজ করতে পারছেন না। দেরিতে মাঠে যেতে হচ্ছে। এখন বোরো মৌসুম। ভুট্টা, মরিচ, গমসহ বিভিন্ন ফসলের বীজ বপন করতে হচ্ছে। শীতের কারণে দেরি করে জমিতে গিয়ে কাজ এগুচ্ছে না বলেও জানান তারা।শীতের কারণে পড়ালেখা স্থবির হয়ে পড়েছে স্কুল-কলেজের শিক্ষার্থীদেরও। সকালে স্কুল শিক্ষার্থী তানিয়া, কাজল ও নাইমা খাতুন জানায়, কনকনে শীত। রাতেও শীতের কারণে পড়তে পারি না। রাতের তাপমাত্রা অনেক কমে যায়। সকালে কুয়াশা আর বাতাসের কারণে প্রাইভেট পড়তে ও স্কুলে যেতে কষ্ট হচ্ছে। &nbsp;এদিকে শীতে প্রকোপে বেড়েছে নানান শীতজনিত রোগ। জ্বর, সর্দি-কাশি, শ্বাসকষ্ট, ডায়রিয়া, নিউমোনিয়াসহ ঠান্ডাজনিত রোগ নিয়ে হাসপাতালগুলোতে ভর্তি হচ্ছেন রোগীরা। উপজেলার স্বাস্থ্য কমপ্লেক্সে প্রতিদিন সকাল থেকে দুপুর ১টা পর্যন্ত শতাধিক রোগী চিকিৎসা নিতে আসছেন। এদের মধ্যে বেশিরভাগই শিশু।চিকিৎসকরা বলেন, আবহাওয়া পরিবর্তনের কারণে রোগীর চাপ বেড়েছে। এমনিতে শীত মৌসুমে আবহাওয়া শুষ্ক থাকায় বাতাসে জীবাণুর পরিমাণ বেড়ে যায়। শীতজনিত রোগ হিসেবে সর্দি-কাশি, শ্বাসকষ্ট বেশি হয়ে থাকে। আর শিশু ও বয়োজ্যেষ্ঠরা শীতজনিত রোগে বেশি আক্রান্ত হয়। তাই এ সময়টাতে বাড়তি সতর্কতা অবলম্বন করতে পারলে কিছুটা হলেও সুরক্ষা মিলবে।তেঁতুলিয়া আবহাওয়া অফিসের ভারপ্রাপ্ত কর্মকর্তা রাসেল শাহ ঢাকা পোস্টকে বলেন, জেলায় গতকালের চেয়ে তাপমাত্রা কমে আজও সর্বনিম্ন তাপমাত্রা রেকর্ড হয়েছে। সকাল ৯টায় ৬ দশমিক ৯ ডিগ্রি সেলসিয়াস রেকর্ড করা হয়েছে। ভোর ৬টায় রেকর্ড করা হয় ৭ দশমিক ৪ ডিগ্রি সেলসিয়াস। গতকাল সোমবার রেকর্ড করা হয়েছিল ৭ ডিগ্রি সেলসিয়াস তাপমাত্রা। আজ কুয়াশা না থাকায় তাপমাত্রা কমেছে ও জেলার ওপর দিয়ে মাঝারি শৈত্যপ্রবাহ বয়ে যাচ্ছে।জেলা প্রশাসক মো.জহুরুল ইসলাম জানিয়েছেন, জেলা প্রশাসনের পক্ষ হতে এ পর্যন্ত চল্লিশ হাজার শীত বিতরণ করা হয়েছে। এ জেলার শীতার্ত মানুষের জন্য আমরা কাজ করে যাচ্ছি। তবে সরকারের পাশাপাশি বেসরকারি প্রতিষ্ঠান ও দানশীল ব্যক্তিদের এগিয়ে আসতে হবে।&nbsp;', NULL, 'untitled-3-202301101016161673381629.jpg', '9767', 'স্বাস্থ্য', 'No', '2023-01-11', '2023-01-11', '02:13AM', NULL, 1, 1, NULL, '2023-01-11 02:13:49am', '2023-01-11 02:15:03', NULL, 'রাজশাহী', '', '', 'আরিফ হোসেন', NULL, '1673381400', 'Noman Abdullah'),
(13, ' আবহাওয়ার খবর', 'Yes', 'No', 'শৈত্যপ্রবাহ অব্যাহত থাকার আভাস', NULL, 'চুয়াডাঙ্গাসহ রাজশাহী ও রংপুর বিভাগের ওপর দিয়ে মৃদু শৈত্যপ্রবাহ বয়ে যাচ্ছে। এ শৈত্যপ্রবাহ অব্যাহত থাকতে পারে বলে জানিয়েছে আবহাওয়া অধিদপ্তর।সোমবার (২৬ ডিসেম্বর) রাতে আবহাওয়া অধিদপ্তরের আবহাওয়াবিদ এ কে এম নাজমুল হক এ তথ্য জানান।Tতিনি জানিয়েছেন,&nbsp;&nbsp;চুয়াডাঙ্গা জেলাসহ রাজশাহী ও রংপুর বিভাগের উপর দিয়ে মৃদু শৈত্যপ্রবাহ বয়ে যাচ্ছে এবং তা অব্যাহত থাকতে পারে।এদিকে মধ্যরাত থেকে সকাল পর্যন্ত দেশের নদী অববাহিকায় ঘন কুয়াশার আভাস দিয়েছে আবহাওয়া অধিদপ্তর। একইসঙ্গে বর্ধিত ৫ দিনের আবহাওয়ার অবস্থায় গুঁড়ি গুঁড়ি বৃষ্টির কথাও জানানো হয়েছে।আগামী ২৪ ঘণ্টার পূর্বাভাসে বলা হয়েছে, অস্থায়ীভাবে মেঘলা আকাশসহ সারাদেশের আবহাওয়া শুষ্ক থাকতে পারে। একইসঙ্গে মধ্যরাত থেকে সকাল পর্যন্ত দেশের নদী অববাহিকায় মাঝারি থেকে ঘন কুয়াশা এবং দেশের অন্যত্র হালকা থেকে মাঝারি ধরনের কুয়াশা পড়তে পারে। এছাড়া সারাদেশের রাত ও দিনের তাপমাত্রা প্রায় অপরিবর্তিত থাকতে পারে।পরবর্তী ৪৮ ঘণ্টার পূর্বাভাসে বলা হয়েছে, বাংলাদেশে তাপমাত্রা হ্রাস পেতে পারে। বর্ধিত ৫ দিনের আবহাওয়ার অবস্থায় বলা হয়েছে, এ সময়ের প্রথমার্ধে তাপমাত্রা বৃদ্ধি পেতে পারে। এছাড়া হালকা বৃষ্টি বা গুঁড়ি গুঁড়ি বৃষ্টি হতে পারে।বর্তমানে ঢাকায় বাতাসের গতিবেগ ঘণ্টায় ৮ থেকে ১২ কিলোমিটার। যা উত্তর বা উত্তর-পশ্চিম দিক থেকে বইছে। সন্ধ্যা ৬টায় ঢাকার বাতাসের আপেক্ষিক আর্দ্রতা ছিল ৭১ শতাংশ। ১০ জানুয়ারি ঢাকায় সূর্যোদয় হবে ভোর ৬টা ৪৩ মিনিটে এবং সূর্যাস্ত যাবে সন্ধ্যা ৫টা ২৮ মিনিটে।গত ২৪ ঘণ্টায় দেশে সর্বোচ্চ ৩০.২ ডিগ্রি সেলসিয়াস তাপমাত্রা রেকর্ড করা হয়েছে শ্রীমঙ্গলে। সর্বনিম্ন ৭ ডিগ্রি সেলসিয়াস তাপমাত্রা রেকর্ড করা হয়েছে তেঁতুলিয়ায়। এছাড়া সারাদেশে কোনো বৃষ্টিপাত রেকর্ড করা হয়নি।', NULL, 'cold-bg-20221229113105-202301092100181673382058.jpg', '1312', 'আবহাওয়া', 'No', '2023-01-11', '2023-01-11', '02:18AM', NULL, 1, NULL, NULL, '2023-01-11 02:20:57am', NULL, NULL, 'খুলনা', NULL, NULL, 'সেজান মাহমুদ', NULL, '1673381880', 'Noman Abdullah'),
(14, '', 'Yes', 'No', 'বঙ্গবন্ধু কাজী নজরুলকে যথাযোগ্য সম্মান দিয়েছেন', NULL, 'সংস্কৃতি প্রতিমন্ত্রী কে এম খালিদ বলেছেন, বঙ্গবন্ধু শেখ মুজিবুর রহমান বাংলাদেশের স্বাধীনতা অর্জনের পরপরই কাজী নজরুল ইসলামকে কলকাতা থেকে সপরিবারে ঢাকায় এনে জাতীয় কবির মর্যাদায় অভিষিক্ত করেন। এর মাধ্যমে বঙ্গবন্ধু কাজী নজরুলকে যথাযোগ্য সম্মান ও মর্যাদা দিয়েছেন।শনিবার (১৪ জানুয়ারি) সন্ধ্যায় রাজধানীর বাংলামোটরে নজরুল সংগীতের একক ভিডিও অ্যালবাম প্রকাশ ও নজরুল সংগীত শিল্পীদের ডিজিটাল ডিরেক্টরি প্ল্যাটফর্মের কাজের উদ্বোধন অনুষ্ঠানে প্রধান অতিথির বক্তৃতায় এসব কথা বলেন। প্রতিমন্ত্রী বলেন, অসচ্ছলতার মধ্য দিয়ে বেড়ে ওঠা কবি নজরুল ৭৭ বছরের জীবনে ৩৪ বছর ১২০ দিন নির্বাক ছিলেন। সব মিলিয়ে সাহিত্যচর্চা করতে পেরেছেন মাত্র ২২ বছর। তাছাড়া নজরুল এমন সময়ে সাহিত্য সাধনা শুরু করেন যখন বাংলা সাহিত্যের বিভিন্ন শাখায় রাজত্ব করছিলেন এবং সাহিত্যে নোবেল পুরস্কার লাভ করেন বিশ্বকবি রবীন্দ্রনাথ ঠাকুর।&nbsp;সংস্কৃতি প্রতিমন্ত্রী বলেন, যদি নজরুল দীর্ঘ সময় নির্বাক না থাকতেন এবং অসচ্ছলতার মধ্য দিয়ে বেড়ে না উঠতেন, তবে বাংলা সাহিত্য জগতে তিনি আকাশকে স্পর্শ করতে পারতেন।অনুষ্ঠানে সভাপতিত্ব ও স্বাগত বক্তব্য রাখেন জেমস অব নজরুলের আহ্বায়ক বিশিষ্ট নজরুল সংগীত শিল্পী সাদিয়া আফরিন মল্লিক। বিশেষ অতিথি হিসেবে বক্তৃতা করেন মিউচুয়াল ট্রাস্ট ব্যাংকের ব্যবস্থাপনা পরিচালক ও প্রধান নির্বাহী কর্মকর্তা সৈয়দ মাহবুবুর রহমান, স্ট্যান্ডার্ড চার্টার্ড ব্যাংকের প্রধান নির্বাহী কর্মকর্তা নাসের এজাজ বিজয় এবং ব্র্যাক বিশ্ববিদ্যালয়ের সাবেক উপাচার্য প্রফেসর সৈয়দ সাদ আন্দালিব।শুদ্ধ সুরে নজরুল সংগীত পরিবেশনার উপযোগিতা নিয়ে আলোচনা করেন বিশিষ্ট কণ্ঠশিল্লী সুমন চৌধুরী। সর্বাধুনিক রেকর্ডিং কার্যক্রম নিয়ে কথা বলেন বিশিষ্ট সংগীত পরিচালক ইবরার টিপু।', NULL, 'mtb-202301142103141673726594.jpg', '1', 'জাতীয়', 'No', '2023-01-15', '2023-01-15', '02:00AM', NULL, 1, NULL, NULL, '2023-01-15 02:03:13am', NULL, NULL, '', NULL, NULL, 'আরিফ হোসেন', NULL, '1673726400', 'Noman Abdullah'),
(15, '', 'Yes', 'No', 'ঢাকায় পৌঁছেছেন ডোনাল্ড লু', NULL, 'দুই দিনের সফরে ঢাকায় পৌঁছেছেন মধ্য ও দক্ষিণ এশিয়াবিষয়ক মার্কিন অ্যাসিসটেন্ট সেক্রেটারি ডোনাল্ড লু। শনিবার (১৪ জানুয়ারি) সন্ধ্যা সাড়ে ৭টার দিকে রাজধানীর হযরত শাহজালাল আন্তর্জাতিক বিমানবন্দরে পৌঁছান তিনি।বিমানবন্দ‌রের এক‌টি সূত্র এ তথ্য নিশ্চিত করেছে। কূট‌নৈ‌তিক সূত্রগু‌লো বল‌ছে, লু’র সফরে র‌্যাবের ওপর নিষেধাজ্ঞা প্রত্যাহার এবং নতুন করে যাতে আর কোনো নিষেধাজ্ঞা আরোপ করা না হয়, সে বিষয়ে যুক্তরাষ্ট্রকে অনুরোধ করবে বাংলাদেশ।অন্যদিকে যুক্তরাষ্ট্রের পক্ষ থেকে, গণতন্ত্র, নির্বাচন, মানবাধিকার, ইন্দো-প্যাসিফিক কৌশল, প্রতিরক্ষা সহযোগিতা, জিজিটাল নিরাপত্তা আইন এবং ঢাকায় দেশটির কূটনীতিকদের নিরাপত্তা নিশ্চিত করার ওপর জোর দিতে পারে।জানা গেছে, সফ‌রে পররাষ্ট্রমন্ত্রী ড. এ কে আব্দুল মোমেন ও পররাষ্ট্রসচিব মাসুদ বিন মোমেনের সঙ্গে বৈঠক করবেন তিনি। এছাড়া লু সরকারি পর্যায়ে আলোচনার পাশাপাশি বাংলাদেশের পরিস্থিতি নিয়ে নাগরিক সমাজের প্রতিনিধিদের সঙ্গে কথা বলবেন। কূটনৈতিক সূত্র আরও বল‌ছে, লু’র সফরে উভয়পক্ষ দ্বিপাক্ষিক ও বহুপাক্ষিক বিষয় নিয়ে আলোচনা করার সম্ভাবনা রয়েছে। এক্ষেত্রে যার যার অগ্রাধিকার ইস্যুগুলো আলোচনার টেবিলে স্থান পাবে। ঢাকার পক্ষ থেকে স্থান পাবে র‌্যাবের ওপর থেকে নিষেধাজ্ঞা প্রত্যাহার, জিএসপি সুবিধা পুনরায় চালু, ব্যবসা-বাণিজ্য, শ্রম অধিকার এবং মানবাধিকার সুরক্ষায় সরকারের নানা উদ্যোগ, অবাধ, সুষ্ঠু ও নিরপেক্ষ নির্বাচনের বিষয়ে এখন পর্যন্ত নেওয়া নানা পদক্ষেপ, ভিয়েনা সনদ অনুযায়ী কূটনীতিকদের নিরাপত্তা নিশ্চিত করা, রোহিঙ্গা ইস্যুতে সহযোগিতার মতো বিষয়গুলো।এছাড়া যুক্তরাষ্ট্রের বোস্টনে পুলিশের গুলিতে বাংলাদেশি নিহতের ঘটনাটি তুলে ধরবে ঢাকা। আরও থাকবে বঙ্গবন্ধুর আত্মস্বীকৃত ও মৃত্যুদণ্ডপ্রাপ্ত খুনি রাশেদ চৌধুরীকে ফেরানোর মতো বিষয়টি।আশা করা হচ্ছে, লু বাংলা‌দে‌শে অবাধ ও সুষ্ঠু নির্বাচন এবং সব দলের অংশগ্রহণের বার্তা দেবেন। পাশাপাশি মানবাধিকার পরিস্থিতি, গুম, ডিজিটাল নিরাপত্তা আইন, ইন্দো-প্যাসিফিক কৌশলসহ নিরাপত্তা সহ‌যো‌গিতা, বি‌শেষ ক‌রে জি‌সো‌মিয়া ও আকসার ম‌তো চু‌ক্তি‌তে বাংলা‌দেশ যেন যুক্ত হয়।গত ৩০ বছর ধরে যুক্তরাষ্ট্র সরকারের হয়ে পররাষ্ট্র কর্মকর্তার দায়িত্ব পালন করছেন ডোনাল্ড লু। ২০২১ সালের সেপ্টেম্বরে যুক্তরাষ্ট্রের দক্ষিণ ও মধ্য এশিয়াবিষয়ক সহকারী পররাষ্ট্রমন্ত্রীর (অ্যাসিসটেন্ট সেক্রেটারি) দায়িত্ব পান লু। এর আগে এ অঞ্চলে একাধিক দেশে সফর করলেও ঢাকায় এটিই তার প্রথম সফর।', NULL, 'lu-202301142040261673726703.jpg', NULL, 'জাতীয়', 'Today Top', '2023-01-15', '2023-01-16', '08:26PM', NULL, 1, 1, NULL, '2023-01-15 02:05:02am', '2023-01-16 20:27:26', NULL, '', '', '', 'মোঃ আব্দুল্লাহ', NULL, '1673726580', 'Noman Abdullah'),
(16, '', 'No', 'No', 'বাড়বে রাতের তাপমাত্রা, সারা দেশে গুঁড়ি গুঁড়ি বৃষ্টির আভাস', NULL, 'জ্যেষ্ঠ প্রতিবেদক১৪ জানুয়ারি ২০২৩, ০৮:৩২ পিএম18Sharesফ+ফ-আগামী ২৪ ঘণ্টায় সারা দেশে রাতের তাপমাত্রা ১ থেকে ২ ডিগ্রি সেলসিয়াস বাড়তে পারে। যা দিনের বেলায় প্রায় অপরিবর্তিত থাকতে পারে। এসময়ে সারা দেশে গুঁড়ি গুঁড়ি বৃষ্টির সম্ভাবনাও রয়েছে বলে জানিয়েছে আবহাওয়া অধিদপ্তর।শনিবার (১৪ জানুয়ারি) আবহাওয়া অধিদপ্তরের আবহাওয়াবিদ এ কে এম নাজমুল হক এ তথ্য জানান।তিনি জানান, আগামী ২৪ ঘণ্টা আংশিক মেঘলা আকাশসহ সারা দেশের আবহাওয়া প্রধানত শুষ্ক থাকতে পারে। তবে রাজশাহী, রংপুর, ঢাকা, ময়মনসিংহ, খুলনা, বরিশাল, চট্টগ্রাম ও সিলেট বিভাগরে দু’এক জায়গায় গুঁড়ি গুঁড়ি/হালকা বৃষ্টি হওয়ার সম্ভাবনা রয়েছে।এই আবহাওয়াবিদ জানান, মধ্যরাত থেকে সকাল পর্যন্ত দেশের নদী অববাহিকা ও তৎসংলগ্ন এলাকায় মাঝারি থেকে ঘন কুয়াশা এবং দেশের অন্যত্র হালকা থেকে মাঝারি ধরনের কুয়াশা পড়তে পারে। এটি কোথাও কোথাও দুপুর পর্যন্ত অব্যাহত থাকতে পারে। এছাড়া নওগাঁ ও মৌলভীবাজারসহ রংপুর বিভাগের ওপর দিয়ে মৃদু থেকে মাঝারি ধরনের শৈত্যপ্রবাহ বয়ে যাচ্ছে এবং তা কিছু কিছু এলাকা থেকে প্রশমিত হতে পারে।নাজমুল হক জানান, আজ দেশের সর্বনিম্ন তাপমাত্রা রেকর্ড করা হয়েছে তেঁতুলিয়ায় ৬.১ ডিগ্রি সেলসিয়াস এবং সর্বোচ্চ তাপমাত্রা রেকর্ড করা হয়েছে টেকনাফে ২৯.৪ ডিগ্রি সেলসিয়াস। এছাড়া গত ২৪ ঘণ্টায় দেশের কোথাও কোনো বৃষ্টিপাত রেকর্ড করা হয়নি। আগামী দুই দিনে রাতের তাপমাত্রা কমলেও আগামী পাঁচ দিনে আবহাওয়া পরিস্থিতিতে উল্লেখযোগ্য পরিবর্তন হওয়ার সম্ভাবনা নেই।', NULL, 'temr-bg-202301142032391673726818.jpg', NULL, 'জাতীয়', 'No', '2023-01-15', '2023-01-15', '02:05AM', NULL, 1, NULL, NULL, '2023-01-15 02:06:57am', NULL, NULL, '', NULL, NULL, 'আরিফ হোসেন', NULL, '1673726700', 'Noman Abdullah'),
(17, '', 'No', 'No', 'সিলেট বিভাগের সব সমস্যা দূর করা হবে : পরিবেশমন্ত্রী', NULL, 'পরিবেশ, বন ও জলবায়ু পরিবর্তন মন্ত্রী মো. শাহাব উদ্দিন বলেছেন, সিলেট বিভাগের সব সমস্যা দূর করা হবে। বর্তমানে কিছু সমস্যা থাকলেও কোনো সমস্যাই সমস্যা থাকবে না। সিলেটবাসীর উন্নয়নের স্বার্থে সবাই মিলে একযোগে কাজ করা হচ্ছে।তিনি বলেন, প্রধানমন্ত্রী সিলেট বিভাগে পাঁচ জন মন্ত্রী উপহার দিয়েছেন, যা ইতোপূর্বে হয়নি। সব মন্ত্রী সিলেট বিভাগের উন্নয়নে কাজ করছেন, ফলে সিলেট বিভাগের রেলপথ, আকাশ পথ ও সড়ক পথে সমানভাবে উন্নয়ন কার্যক্রম বাস্তবায়ন করা হচ্ছে। শনিবার (১৪ জানুয়ারি) সন্ধ্যায় ডিপ্লোমা ইঞ্জিনিয়ার্স ইনস্টিটিউশন মিলনায়তনে সিলেট বিভাগ যোগাযোগ ও উন্নয়ন পরিষদের কার্যনির্বাহী কমিটির অভিষেক অনুষ্ঠানে এসব কথা বলেন মো. শাহাব উদ্দিন।মন্ত্রী বলেন, মৌলভীবাজারের লাঠিটিলায় সাফারি পার্ক নির্মাণ করা হচ্ছে। মাধবকুণ্ড জলপ্রপাতে কেবল কার স্থাপন করার প্রক্রিয়া এগিয়ে চলছে। হাওর বাওর জলাভূমির সিলেট বিভাগের হাওর ও জলাশয় খননকাজ বাস্তবায়ন করা হচ্ছে। বর্তমান সরকারের আমলে দেশের সব জেলা, উপজেলা, ইউনিয়ন, গ্রাম, পরিবার সবার উন্নয়ন হয়েছে।সিলেট বিভাগ যোগাযোগ ও উন্নয়ন পরিষদের সভাপতি ড. আহমেদ আল কবিরের সভাপতিত্বে অনুষ্ঠিত অনুষ্ঠানে আরও বক্তব্য দেন পররাষ্ট্রমন্ত্রী ড. এ কে আব্দুল মোমেন, বেসরকারি বিমান পরিবহন ও পর্যটন প্রতিমন্ত্রী অ্যাডভোকেট মাহবুব আলী, হবিগঞ্জ-৪ আসনের সংসদ সদস্য শাহনেওয়াজ মিলাদ গাজী এবং পল্লী কর্ম সহায়ক ফাউন্ডেশনের চেয়ারম্যান ও অর্থনীতিবিদ ড. কাজী খলিকুজ্জামান আহমদ প্রমুখ।', NULL, 'shab-uddin-202301141859171673726902.jpg', NULL, 'জাতীয়', 'No', '2023-01-15', '2023-01-15', '02:07AM', NULL, 1, NULL, NULL, '2023-01-15 02:08:22am', NULL, NULL, 'সিলেট', 'সিলেট', '', 'আরিফ হোসেন', NULL, '1673726820', 'Noman Abdullah'),
(18, '', 'No', 'No', 'কেরানীগঞ্জে বিদ্যুৎস্পৃষ্টে রাজমিস্ত্রির মৃত্যু', NULL, 'কেরানীগঞ্জের বসুন্ধরা আবাসিক এলাকায় একটি ভবনের দ্বিতীয় তলায় কাজ করার সময় বিদ্যুৎস্পৃষ্ট হয়ে সাজু আহমেদ (২৪) নামে এক রাজমিস্ত্রির মৃত্যু হয়েছে।শনিবার (১৪ জানুয়ারি) সন্ধ্যায় তাকে অচেতন অবস্থায় উদ্ধার করে ঢাকা মেডিকেল কলেজ (ঢামেক) হাসপাতালের জরুরি বিভাগের নিয়ে গেলে কর্তব্যরত চিকিৎসক পরীক্ষা-নিরীক্ষা শেষে মৃত ঘোষণা করেন।ADVERTISEMENTমৃত সাজুর সহকর্মী চাঁদ আলী ঢাকা পোস্টকে বলেন, সাজু এই ভবনে রাজমিস্ত্রির কাজ করতেন। কাজ করার সময় বৈদ্যুতিক তারের সঙ্গে জড়িয়ে পড়েন। পরে সে অচেতন হয়ে পড়ে। তাকে উদ্ধার করে ঢাকা মেডিকেলে নিয়ে এলে কর্তব্যরত চিকিৎসক মৃত ঘোষণা করেন।তিনি আরও জানান, সাজু ওই ভবনেই থাকতো। তার বাড়ি শেরপুর জেলার ঝিনাইগাতি থানা এলাকায়।ঢামেক হাসপাতালের পুলিশ ক্যাম্পের ইনচার্জ পরিদর্শক বাচ্চু মিয়া ঢাকা পোস্টকে বলেন, মরদেহটি হাসপাতালের জরুরি বিভাগের মর্গে রাখা হয়েছে। বিষয়টি সংশ্লিষ্ট থানাকে জানানো হয়েছে।', NULL, 'death-202301141839451673727010.jpg', '1', 'জাতীয়', 'No', '2023-01-15', '2023-01-15', '02:09AM', NULL, 1, NULL, NULL, '2023-01-15 02:10:09am', NULL, NULL, 'ঢাকা', '', NULL, 'আরিফ হোসেন', NULL, '1673726940', 'Noman Abdullah'),
(19, '', 'No', 'No', '‘নির্বাচনে জয় পেতে কোন্দল নিরসন করতে হবে’', NULL, 'তৃণমূলের কোন্দল এবং সংগঠনকে ঐক্যবদ্ধ করতে পারলেই আগামী দ্বাদশ জাতীয় সংসদ নির্বাচনে জয়ী হতে পারবে বলে মনে করছেন আওয়ামী লীগের সদ্য নবনির্বাচিত জাতীয় কমিটি ও উপদেষ্টা পরিষদের সদস্যরা। তারা আগামী নির্বাচনের পূর্বে&nbsp;দলীয় কোন্দল নিরসনের জন্য দলের সভাপতিকে উদ্যোগ নেওয়ার পরামর্শ দিয়েছেন বলে বৈঠকে উপস্থিত একাধিক নেতা ঢাকা পোস্টকে নিশ্চিত করেছেন।শনিবার (১৪ জানুয়ারি) দুপুর সোয়া ১২টায় প্রধানমন্ত্রীর বাসভবন গণভবনে আওয়ামী লীগের উপদেষ্টা পরিষদ, জাতীয় পরিষদ এবং কেন্দ্রীয় কার্যনির্বাহী সংসদের যৌথসভার মুলতবি সভা শুরু হয়। যৌথসভার মাঝে মধ্যাহ্ন ভোজের এক ঘন্টা বিরতি দিয়ে চলে বিকেল সাড়ে ৪টা পর্যন্ত। দলের সভাপতি ও প্রধানমন্ত্রী শেখ হাসিনার সভাপতিত্বে যৌথসভায় ২০ জন নেতা বক্তব্য দেন। তাদের মধ্যে রয়েছেন- অ্যাম্বাসেডর মোহাম্মদ জমির, সাহাবুদ্দিন চুপ্পু, রশিদুল আলম, খন্দকার গোলাম মওলা নকশাবন্দী, ইনাম আহমেদ চৌধুরী, অধ্যাপিকা সাদেকা হালিম, বজলুর রশিদ, সুলতানা সাফি, চন্দন শীল, খলিলুর রহমান মণ্ডল, অধ্যক্ষ জোবায়দা খাতুন পারুল প্রমুখ।ADVERTISEMENTবৈঠকে উপস্থিত একাধিক নেতা ঢাকা পোস্টকে বলেন, ‘দলের কেন্দ্রীয় কার্যনির্বাহী সংসদের কোনো নেতা বক্তব্য না দিলেও উপদেষ্টা ও জাতীয় কমিটির বেশিভাগ নেতার বক্তব্যে বলেছেন যে, আওয়ামী লীগের মূল সমস্যা দলের কোন্দল। নির্বাচনের আগে সে কোন্দল কমাতে হবে। বিএনপির সাংগঠনিক অবস্থা আওয়ামী লীগের চেয়ে ভালো নয়। বিএনপির চেয়ে আওয়ামী লীগ অনেক শক্তিশালী। কিন্তু আমাদের দলের মূল সমস্যা হলো নিজেদের নেতাদের মাঝে কোন্দল। আওয়ামী লীগের শত্রু আওয়ামী লীগ। নির্বাচনের আগে সব মিটিয়ে ফেলতে হবে। তাহলে আমরা আগামী নির্বাচনে জয় লাভ করতে পারবো’ বলে দলের সভাপতিকে তৃণমূলের কোন্দল মেটানোর উদ্যোগ নেওয়ার আহ্বান জানান উপদেষ্টারা।বৈঠকে উপস্থিত এক সাংগঠনিক সম্পাদক ঢাকা পোস্টকে বলেন, ‘তৃণমূলে কাজ করার জন্য নির্দেশ দিয়েছেন আওয়ামী লীগের সভাপতি। আগামী নির্বাচনের পূর্বে আওয়ামী লীগে সব উন্নয়ন তুলে ধরতে নির্দেশ দিয়েছেন। আওয়ামী লীগের একাধিক উপদেষ্টার বক্তব্যে ছিল কীভাবে তৃণমূলকে সুসংগঠিত করা যায়। তাদের (উপদেষ্টা) বক্তব্যের জবাবে আওয়ামী লীগ সভাপতি বলেন, ‘আমাদের নেত্রী &nbsp;বলেছেন, সংগঠনকে ঐক্যবদ্ধ করতে ও সমস্যা সমাধানের জন্য কেন্দ্রের সঙ্গে জেলার সমন্বয় করে কাজ করতে হবে। তার জন্য জাতীয় কমিটি ও উপদেষ্টা পরিষদকে কাজ করার আহ্বান জানান তিনি।’সূত্র মতে, আওয়ামী লীগ সব সময় নির্বাচনমুখী সংগঠন। নির্বাচনকে সামনে রেখে একটি শ্রেণি সক্রিয় হয়ে উঠেছে। সবাইকে সজাগ ও সতর্ক থাকতে হবে। নিজেদের মধ্যে বিভেদ ভুলে যেতে হবে। দলকে ঐক্যবদ্ধভাবে এগিয়ে নিতে হবে। ঐক্যবদ্ধ আওয়ামী লীগকে কেউ হারাতে পারবে না।এদিকে বৈঠকের শুরুতে সূচনা বক্তব্যে দেন আওয়ামী লীগের সভাপতি শেখ হাসিনা। তিনি বলেন, ‘শুধু মুখে মুখে (দুর্নীতির কথা) বললে তো হবে না। এখন এমন লোকজনের কাছ থেকে আমাকে শুনতে হচ্ছে, যারা নিজেরাই দুর্নীতিগ্রস্ত। যাদের আমলে দুর্নীতিতে বাংলাদেশ চ্যাম্পিয়ন হয়েছে। ক্ষুদ্রঋণের ব্যবসা করতে গিয়ে গরিব মানুষের ওপর এমন চাপ যে, সুদ দিতে দিতে তাদের অনেক সময় বাড়ি-ঘর ছেড়ে এলাকা থেকে চলে যেতে হয়েছে অথবা আত্মহত্যা করতে হয়েছে।’&nbsp;প্রধানমন্ত্রী বলেন, ‘গত ১৪ বছরে সরকার দেশের অনেক উন্নয়ন করেছে। করোনার পরে বিশ্বমন্দার মাঝে মানুষের জীবনযাত্রা সহজ করতে বিভিন্ন খাতে ভর্তুকি দেওয়া হয়েছে। কিন্তু এখন নিজের পায়ে দাঁড়ানোর কথা চিন্তা করতে হবে। নিজস্ব উৎপাদনের মাধ্যমে নিজেদের চাহিদা মেটানোর ব্যবস্থা করতে হবে। মন্দার কারণে সরকার অনেক হিসাব-নিকাশ করে চলছে।’আওয়ামী লীগ সভাপতি বলেন, ‘গরিব মানুষের টাকা দিয়েই কিন্তু তারা দেশে নাম-টাম করে কিন্তু বেশ ভালোই আছেন এবং প্রচুর অর্থ-সম্পদের মালিক হয়েছেন। পৃথিবীর বিভিন্ন দেশে বিনিয়োগও করেছেন। এ টাকাগুলো কোথা থেকে এলো? এগুলো গরিবের রক্তচোষা টাকা। এটা তো বাস্তব কথা।’এর আগে গত ৭ জানুয়ারি আওয়ামী লীগের নবনির্বাচিত জাতীয় কমিটি, কেন্দ্রীয় কার্যনির্বাহী সংসদ ও উপদেষ্টা পরিষদের যৌথ সভা অনুষ্ঠিত হয়। সেদিন দুপুর ২টায় টুঙ্গিপাড়া উপজেলা আওয়ামী লীগের কার্যালয়ে দলের জাতীয় কমিটি, কেন্দ্রীয় কার্যনির্বাহী সংসদ ও উপদেষ্টা পরিষদের সদস্যরা এ যৌথ সভায় অংশগ্রহণ করেন। সভায় সভাপতিত্ব করেছিলেন আওয়ামী লীগ সভাপতি শেখ হাসিনা। সেদিন যৌথসভা মুলতবি করা হয়। আজ সে মুলতবি সভাটি অনুষ্ঠিত হয়।', NULL, '12-awami-league-20220626192-202301142358391673727116.webp', NULL, 'রাজনীতি', 'No', '2023-01-15', '2023-01-15', '02:10AM', NULL, 1, NULL, NULL, '2023-01-15 02:11:55am', NULL, NULL, '', NULL, NULL, 'আরিফ হোসেন', NULL, '1673727000', 'Noman Abdullah'),
(20, '', 'No', 'No', 'জাতির সামনে সঠিক ইতিহাস তুলে ধরার সময় চলে এসেছে : মঈন খান', NULL, 'একটি দেশের সত্যিকারের পরিচয় সেখানকার শিক্ষা ও সংস্কৃতি বলে মন্তব্য করেছেন বিএনপির স্থায়ী কমিটির সদস্য ড. আব্দুল মঈন খান। তিনি বলেন, আজ সেই সত্যিকারের শিক্ষা-সংস্কৃতি ও ইতিহাস থেকে আমাদের কোমলমতি বালক-বালিকাদের বিচ্ছিন্ন করে দেওয়ার কাজ চালানো হচ্ছে। আমাদের উচিত এখন জাতির সামনে সঠিক ইতিহাস তুলে ধরা। সেজন্য কাজ করতে হবে।শনিবার (১৪ জানুয়ারি) দুপুরে জাতীয় প্রেস ক্লাবে প্রফেশনালস মুভমেন্ট অব বাংলাদেশ আয়োজিত ‘শিক্ষা ব্যবস্থায় বিজাতীয় আগ্রাসন’ শীর্ষক আলোচনা সভায় এসব কথা বলেন মঈন খান।ADVERTISEMENTতিনি বলেন, বাংলাদেশের সরকার দেশ শাসন করে না। তারা বসে বসে ইতিহাস লেখে। কিন্তু সেটা সত্যিকারের ইতিহাস নয়, কাল্পনিক ইতিহাস। আজকের যে পাঠ্যবইয়ের সমস্যা, এটি আসলে পাঠ্যবইয়ের সমস্যা না। পাঠ্যবইয়ের প্রথম পৃষ্ঠায় যে ছবি রয়েছে সেটি বাংলাদেশের কোথাও কি দেখা যায়? যদি না দেখা যায় তবে এটি আমাদের কোমলমতি ছেলে-মেয়েদের মধ্যে কীভাবে গেল?দেশের পরিচয় শুধু উন্নয়ন দিয়ে হয় না— উল্লেখ করে মঈন খান বলেন, উন্নয়নের নামে দুর্নীতি দিয়েও একটি দেশের পরিচয় হয় না। একটি শিশু যখন স্কুল-কলেজে যাবে তখন তাকে মুক্তচিন্তা করার সুযোগ করে দিতে হবে। তার সামনে সব তথ্য তুলে ধরতে হবে। সে যখন বড় হবে তখন সে নিজেই বুঝতে পারবে কোনটা করা ঠিক হবে আর কোনটা বেঠিক হবে।বিশিষ্ট রাষ্ট্রবিজ্ঞানী অধ্যাপক দিলারা চৌধুরী বলেন, যখন বইগুলো ছাপানো হয় তখন আমাদের প্রতিবাদ করা উচিত ছিল। প্রতিবাদ এমন একটি জিনিস সেটা সবসময় করে যেতেই হবে। প্রতিবাদ করলে সমাধান হয় আবার সমস্যার সৃষ্টি হয়। তাই প্রতিবাদকে চালিয়ে যেতে হয়। যারা স্বৈরাচারী, যারা মানুষের অধিকার থেকে মানুষকে বঞ্চিত করে তারা কিন্তু বারবার পৃথিবীর ইতিহাসে আত্মমোচন করেছেন।ADVERTISEMENTআলোচনা সভায় মূল প্রবন্ধ উপস্থাপন করেন পটুয়াখালী বিজ্ঞান ও প্রযুক্তি বিশ্ববিদ্যালয়ের সাবেক উপাচার্য (ভিসি) প্রফেসর আবদুল লতিফ মাসুম।শিক্ষক-কর্মচারী ঐক্যজোটের চেয়ারম্যান অধ্যক্ষ মো. সেলিম ভূঁইয়ার সভাপতিত্বে আরও বক্তব্য রাখেন তাজমেরী ইসলাম, জয়নুল আবেদীন, সৈয়দ জয়নুল আবেদীন মেসবাহ প্রমুখ।', NULL, 'moin-khan-202301141719041673727195.jpg', NULL, 'রাজনীতি', 'No', '2023-01-15', '2023-01-15', '02:12AM', NULL, 1, NULL, NULL, '2023-01-15 02:13:15am', NULL, NULL, 'রাজশাহী', NULL, NULL, 'আরিফ হোসেন', NULL, '1673727120', 'Noman Abdullah'),
(21, '', 'No', 'No', 'ফরিদপুরে পুলিশ আক্রমণকারী নয়, তারা আক্রান্ত : ওবায়দুল কাদের', NULL, 'আওয়ামী লীগের সাধারণ সম্পাদক ওবায়দুল কাদের বলেছেন, ইদানিং আমরা লক্ষ্য করছি হঠাৎ করে বাস পোড়ানো হচ্ছে, যেটা ফরিদপুরে ঘটেছে। সেখানে পুলিশের ওপর আক্রমণ করেছে, সেখানের সবাই একবাক্যে বলেছে যে, পুলিশ আক্রমণকারী নয়, তারা আক্রান্ত।শনিবার (১৪ জানুয়ারি) বিকেলে আওয়ামী লীগের সভাপতির ধানমন্ডির রাজনৈতিক কার্যালয়ে দলের সম্পাদকমণ্ডলীর সঙ্গে ঢাকা মহানগর দক্ষিণ ও উত্তর এবং সহযোগী সংগঠনের শীর্ষ নেতাদের এক যৌথসভায় তিনি এসব কথা বলেন।ওবায়দুল কাদের বলেন, আওয়ামী লীগ সরকারের উন্নয়ন কর্মকাণ্ডে দেশের মানুষ খুশি, আর বিএনপির প্রতি জনগণের কোনো আস্থা নেই। আগামী নির্বাচনেও বিএনপির জেতার কোনো সম্ভাবনা নেই, সেটা তারা জানে। তাই তারা দেশে একটি অস্থিতিশীল পরিস্থিতি সৃষ্ট করতে চয়। তাদের উদ্দেশ্য ষড়যন্ত্রের মাধ্যমে শেখ হাসিনার সরকারকে হটাবে।আবারও ১/১১’র মতো পরিস্থিতি সৃষ্টি করতে চায় জানিয়ে তিনি বলেন, বিএনপি ভেতরে ভেতরে নির্বাচনের প্রস্তুতি নিলেও নির্বাচনে জিতবে এমন কোনো আশ্বস্ত হতে পারছে না। তাই তারা ষড়যন্ত্রের মাধ্যমে চোরাই পথে ক্ষমতা দখলের চেষ্টা করছে। একটা ওয়ান ইলেভেন হয়েছে, আরেকটা ওয়ান ইলেভেনের জন্য পাঁয়তারা করছে। এই লক্ষ্যে তারা অশুভ খেলায় মেতে উঠেছে।‘প্রধানমন্ত্রী শেখ হাসিনার নির্দেশের আলোকে আমরা নিজেদের প্রস্তুত রাখব। আমরা ক্ষমতায় রয়েছি তাই এই দেশের জনগণের জানমালের নিরাপত্তার বিষয়টি অবশ্যই আমাদের দেখতে হবে। আন্দোলনের নামে ভাঙচুর অগ্নি সংযোগ করে তারা জনজীবনে দুর্ভোগ ডেকে আনবে, রাস্তা অবরোধ করে বিশৃঙ্খলা ডেকে আনবে এই অবস্থায় আমরা চুপ থাকতে পারি না।ADVERTISEMENTওবায়দুল কাদের বলেন, আমরা জনগণের ওয়াদা দিয়ে ভোট নিয়েছি, তাই তাদের কাছে আমাদের দায় রয়েছে। আন্দোলনের নামে সহিংসতা নাশকতা হলে অবশ্যই সতর্ক থাকতে হবে, জনগণের জানমালের নিরাপত্তা দিতে হবে। সেজন্যই আমরা আজকে এই সভা ডেকেছি। তারা যত কথাই বলুক আমরা আমাদের অবস্থানে সতর্ক আছি।&nbsp;‘আজকে আমাদের দলের নেতা-কর্মীদের নিয়ে দুপুর ১২টা থেকে বিকেল সাড়ে ৪টা পর্যন্ত আমাদের নেত্রী সভা করেছে। সভা শেষে আমরা এখানে যৌথসভায় এসেছি। আমরা আরও সতর্ক থাকব, আমাদের নেতা-কর্মীদের আরও সুদৃঢ় করতে হবে। আরও শক্ত অবস্থানে থাকতে হবে। যেকোনো ধরনের নাশকতা করে দেশকে অস্থিতিশীল পরিস্থিতি সৃষ্টির পাঁয়তারা করতে চাইলে প্রতিরোধ করা হবে, প্রতিহত করা হবে।’যুক্তরাষ্ট্রের একজন মন্ত্রী পদমর্যাদার সদস্য বাংলাদেশে আসার প্রসঙ্গে জানতে চাইলে ওবায়দুল কাদের বলেন, যুক্তরাষ্ট্রের একজন সহকারী পররাষ্ট্রমন্ত্রী, যিনি দক্ষিণ এশিয়া ও মধ্য এশিয়ার দায়িত্বপ্রাপ্ত। তিনি আসতেই পারেন, সফর বিনিময় হতেই পারে। এটা একটা স্বাভাবিক বিষয়, এটা নিয়ে নতুন করে বিস্মিত হওয়ার কিছু নেই।&nbsp;‘তিনি এসেছেন, মন্ত্রীদের সঙ্গে, বিশেষ করে পররাষ্ট্রমন্ত্রীর সঙ্গে কথা বলবেন, এখানে আমাদের পার্টির কোনো বিষয় না। আসছেন উভয়ের কথা বলুক, শুনি কি বলে।’যৌথসভায় আওয়ামী লীগের যুগ্ম সাধারণ সম্পাদক হাছান মাহমুদ, আ ফ ম বাহাউদ্দিন নাছিম, ডা. দীপু মনি, সাংগঠনিক সম্পাদক আহমেদ হোসেন, প্রচার ও প্রকাশনা সম্পাদক আবদুস সুবহান গোলাপ, দপ্তর সম্পাদক বিপ্লব বড়ুয়া, বিজ্ঞান ও প্রযুক্তিবিষয়ক সম্পাদক ইঞ্জি. আবদুস সবুর, &nbsp;ঢাকা মহানগর উত্তর দক্ষিণ আওয়ামী লীগ, যুবলীগ, ছাত্রলীগ, স্বেচ্ছাসেবক লীগ, শ্রমিক লীগ, কৃষক লীগ, মহিলা আওয়ামী লীগ, যুব মহিলা আওয়ামী লীগ নেতারা উপস্থিত ছিলেন।', NULL, 'kader-202301141820181673727308.jpg', NULL, 'রাজনীতি', 'No', '2023-01-15', '2023-01-15', '02:13AM', NULL, 1, NULL, NULL, '2023-01-15 02:15:08am', NULL, NULL, 'ঢাকা', 'ফরিদপুর', 'আলফাডাঙ্গা', 'আরিফ হোসেন', NULL, '1673727180', 'Noman Abdullah'),
(22, '', 'No', 'No', 'ক্ষমতার ভারসাম্য জরুরি হয়ে পড়েছে : চুন্নু', NULL, 'বাংলাদেশের সব ক্ষমতা একজনের হাতে বলে দাবি করেছেন জাতীয় পার্টি মহাসচিব মো. মুজিবুল হক চুন্নু। তিনি বলেছেন, একজনের হাতে সব ক্ষমতা থাকলে তিনি স্বৈরাচার হতে বাধ্য। ক্ষমতার ভারসাম্য জরুরি হয়ে পড়েছে। প্রয়োজনে সংবিধান সংশোধন করে ক্ষমতার ভারসাম্য সৃষ্টি করা উচিত।শনিবার (১৪ জানুয়ারি) দুপুরে ডেমোক্রেসি ইন্টারন্যাশনাল আয়োজিত জাতীয় পার্টির নেতা-কর্মীদের সঙ্গে ‌‘ক্ষমতা শক্তিশালী করণের ওপর কৌশলগত এক পরিকল্পনা’ কর্মশালায় এসব কথা বলেন তিনি।&nbsp;ADVERTISEMENTচুন্নু বলেন, সংবিধানের ৭০ ধারার কারণে সংসদ সদস্যদের মুখ বন্ধ হয়ে আছে। আবার, যিনি ক্ষমতাসীন দলে প্রধান তিনিই প্রধানমন্ত্রী হিসেবে নির্বাহী বিভাগের প্রধান। আবার আইনসভার প্রধানও তিনি। সংবিধানের ৪৮ ধারার কারণে রাষ্ট্রপতি প্রায় সব সিদ্ধান্তে প্রধানমন্ত্রীর পরামর্শ নিতে বাধ্য। তাই সাংবিধানিকভাবেই সব ক্ষমতা এক ব্যক্তির হাতে ন্যস্ত হয়েছে।মুজিবুল হক চুন্নু বলেন, দুর্নীতি, দুঃশাসন, চাঁদাবাজী, টেন্ডারবাজী ও দলবাজীর কারণে দেশের মানুষ আওয়ামী লীগ ও বিএনপি’র ওপর অনাস্থা প্রকাশ করেছে। দেশের মানুষ আর আওয়ামী লীগ ও বিএনপিকে রাষ্ট্র ক্ষমতায় দেখতে চায় না।জাতীয় পার্টির ভাইস চেয়ারম্যান আহসান আদেলুর রহমানের পরিচালনায় অনুষ্ঠিত কর্মশালায় ডেমোক্রেসি ইন্টারন্যাশনালের উপস্থিত ছিলেন চিফ অব পার্টি ডানা আই গোল্ড ড. মো. আব্দুল আলিম, গোলাম মোস্তফা, লিপিকা বিশ্বাস, সাম্মি লায়লা ইসলাম।&nbsp;', NULL, 'chunnu-202301141612591673727372.jpg', NULL, 'রাজনীতি', 'No', '2023-01-15', '2023-01-15', '02:15AM', NULL, 1, NULL, NULL, '2023-01-15 02:16:12am', NULL, NULL, 'চট্টগ্রাম', NULL, NULL, 'আরিফ হোসেন', NULL, '1673727300', 'Noman Abdullah'),
(23, '', 'No', 'No', 'জিয়াউর রহমানের জন্মবার্ষিকীতে বিএনপির কর্মসূচি', NULL, 'বিএনপির প্রতিষ্ঠাতা জিয়াউর রহমানের ৮৭তম জন্মবার্ষিকী উপলক্ষে একগুচ্ছ কর্মসূচি ঘোষণা করেছে দলটি। শনিবার (১৪ জানুয়ারি) দুপুরে নয়াপল্টনে বিএনপির যৌথসভা শেষে কর্মসূচি ঘোষণা করেন মহাসচিব মির্জা ফখরুল ইসলাম আলমগীর।মির্জা ফখরুল বলেন, কর্মসূচির মধ্যে রয়েছে ১৯ জানুয়ারি সকাল ৬টায় নয়াপল্টনে কেন্দ্রীয় কার্যালয়ে দলীয় পতাকা উত্তোলন। ওই দিন বেলা ১১টায় বিএনপির কেন্দ্রীয় নেতারা শেরেবাংলা নগরের জিয়াউর রহমানের মাজারে ফাতেহা পাঠ ও পুষ্পার্ঘ্য অর্পণ করবেন। পরে বিকেল ৩টায় রমনায় ইনস্টিটিউট অব ইঞ্জিনিয়ার্স মিলনায়তনে আলোচনা সভা অনুষ্ঠিত হবে।ADVERTISEMENTজিয়াউর রহমানের জন্মবার্ষিকী উপলক্ষে দৈনিক সংবাদপত্রে ক্রোড়পত্র প্রকাশিত হবে বলে উল্লেখ করে বিএনপি মহাসচিব বলেন, ঢাকাসহ দেশের জেলা, উপজেলা, মহানগর ও পৌরসভায় দোয়া ও আলোচনা সভা অনুষ্ঠিত হবে।১৭ জানুয়ারি মহিলা দলের উদ্যোগে আলোচনা সভা ও শীতবস্ত্র বিতরণ করা হবে উল্লেখ করে মির্জা ফখরুল জানান, ১৮ জানুয়ারি ছাত্রদলের উদ্যোগে রক্তদান কর্মসূচি, চিত্রাঙ্কন প্রতিযোগিতা, দুস্থ শিক্ষার্থীদের মাঝে শিক্ষা উপকরণ বিতরণ এবং ছিন্নমূল শিশু-কিশোরদের মধ্যে শীতবস্ত্র বিতরণ করা হবে। ওলামা দল ওই দিন এতিম শিশুদের মাঝে পবিত্র কুরআন ও খাদ্য বিতরণ করবে।&nbsp;মির্জা ফখরুল বলেন, ২০ জানুয়ারি জাতীয়তাবাদী সামাজিক সাংস্কৃতিক সংস্থার (জাসাস) উদ্যোগে সাংস্কৃতিক অনুষ্ঠানের আয়োজন করা। এছাড়া ২১ জানুয়ারি জাতীয়তাবাদী শ্রমিক দল, ২২ জানুয়ারি মুক্তিযোদ্ধা দলের আলোচনা সভা ও শীতবস্ত্র বিতরণ ও ২৩ জানুয়ারি কৃষক দলের উদ্যোগে সেমিনার অনুষ্ঠিত হবে।&nbsp;ADVERTISEMENT১৯ জানুয়ারি রাতে ঢাকা মহানগর উত্তর-দক্ষিণ তাদের নিজস্ব উদ্যোগে রাজধানীর বিভিন্ন স্থানে গরিব ও অসহায়দের মাঝে শীতবস্ত্র বিতরণ করবে বলেও জানান মির্জা ফখরুল।২৪ জানুয়ারি যুবদল ও ২৬ জানুয়ারি স্বেচ্ছাসেবক দলের উদ্যোগে আলোচনা সভা ও শীতবস্ত্র বিতরণ করা হবে বলে উল্লেখ করেন মির্জা ফখরুল।১৯৩৬ সালের ১৯ জানুয়ারি বগুড়া জেলার বাগবাড়ী গ্রামে জন্মগ্রহণ করেন জিয়াউর রহমান।', NULL, 'dhakapost-202301141425061673727455.jpg', NULL, 'রাজনীতি', 'No', '2023-01-15', '2023-01-15', '02:16AM', NULL, 1, NULL, NULL, '2023-01-15 02:17:35am', NULL, NULL, '', NULL, NULL, 'আরিফ হোসেন', NULL, '1673727360', 'Noman Abdullah'),
(24, '', 'No', 'No', 'বাণিজ্য মেলায় বে‌শি দামে পণ্য বিক্রি, দিচ্ছে না প্রতিশ্রুত সেবা', NULL, 'ঢাকা আন্তর্জাতিক বাণিজ্য মেলায় নির্ধারিত মূল্যের চে‌য়ে বেশি দামে পণ্য বিক্রি করা হচ্ছে। প্রতিশ্রুতি অনুযায়ী ক্রেতা‌কে দেওয়া হচ্ছে না পণ্য ও সেবা। এমন অভি‌যোগ উঠেছে বেশ কিছু প্রতিষ্ঠানের বিরুদ্ধে। এতে বিপাকে প‌ড়ছেন মেলায় আসা ক্রেতা দর্শনার্থীরা।শনিবার (১৪ জানুয়ারি) মেলা প্রাঙ্গণে জাতীয় ভোক্তা অধিকার সংরক্ষণ অধিদপ্তরের মনিটরিং ও সাধারণ ক্রেতা‌দের অভিযোগে এ তথ্য উঠে এসেছে। এসব অপরাধে বাণিজ্য মেলায় তিন প্রতিষ্ঠানকে জরিমানার পাশাপাশি সতর্ক করেছে অধিদপ্তর।ADVERTISEMENTঅধিদপ্তরের উপ-পরিচালক (প্রশিক্ষণ ও প্রচার) আতিয়া সুলতানা জানান, বাণিজ্য মেলা চলাকালে নিয়মিত কার্যক্রমের অংশ হিসেবে আজও মনিটরিং করা হয়। এসময় নির্ধারিত মূল্যের চে‌য়ে বেশি দামে পণ্য বিক্রি ও প্রতিশ্রুতি অনুযায়ী পণ্য-সেবা না দেওয়ার অপরাধে তিন প্রতিষ্ঠানকে ৯ হাজার টাকা জরিমানার পাশাপাশি সতর্ক করা হয়েছে।অধিদপ্তরের উপ-পরিচালক (গবেষণা) রিনা বেগমের নেতৃত্বে অভিযানে সহযোগিতা করেন সহকারী পরিচালক (অভিযোগ) মুহাম্মদ হাসানুজ্জামান, অধিদপ্তরের কর্মচারী এবং নারায়ণগঞ্জ জেলা পুলিশের একটি টিম। জনস্বার্থে এসব কার্যক্রম অব্যাহত থাকবে বলে জানিয়েছে অধিদপ্তর।গত ১ জানুয়ারি মাসব্যাপী আন্তর্জাতিক বাণিজ্য মেলার উদ্বোধন করেন প্রধানমন্ত্রী শেখ হাসিনা। এটি ঢাকার ২৭তম আন্তর্জাতিক বাণিজ্য মেলা। ১৯৯৫ সাল থেকে বাণিজ্য মন্ত্রণালয় ও রপ্তানি উন্নয়ন ব্যুরোর যৌথ উদ্যোগে আন্তর্জাতিক বাণিজ্য মেলা অনুষ্ঠিত হয়ে আসছে। দেশীয় পণ্যের প্রচার, প্রসার, বিপণন ও উৎপাদনে সহায়তার জন্য এ মেলার আয়োজন করা হয়। আগে বাণিজ্য মেলা শেরে বাংলা নগরের চীন-মৈত্রী সম্মেলন কেন্দ্রের পাশের খোলা মাঠে অনুষ্ঠিত হতো। ২০২২ সাল থেকে পূর্বাচলের বঙ্গবন্ধু বাংলাদেশ-চায়না ফ্রেন্ডশিপ এক্সিবিশন সেন্টার প্রাঙ্গণ মেলার জন্য নির্ধারিত হয়েছে।ADVERTISEMENTএবারের বাণিজ্য মেলায় ১০টি দেশের ১৭টি প্রতিষ্ঠান অংশ নিয়েছে। মেলা প্রতিদিন সকাল ১০টা থেকে রাত ৯টা পর্যন্ত খোলা থাকছে। তবে সাপ্তাহিক বন্ধের দিন রাত ১০টা পর্যন্ত মেলা চলে। এবার মেলায় প্রবেশ মূল্য নির্ধারণ করা হয়েছে প্রাপ্তবয়স্কদের জন্য ৪০ টাকা এবং অপ্রাপ্ত বয়স্কদের জন্য ২০ টাকা। মেলার টিকিট অনলাইনে কিনলে ৫০ শতাংশ ছাড়ের সুযোগ থাকবে। এছাড়াও মেলায় প্রায় এক হাজার গাড়ি পার্কিংয়ের ব্যবস্থাসহ বিদেশি প্রতিষ্ঠানের জন্য ১৭টি প্যাভিলিয়ন, মিনি প্যাভিলিয়ন ও স্টল রয়েছে। দেশি ও বিদেশি প্রতিষ্ঠানের জন্য দুটি হলের বাইরে মিলে মোট ৩৩১টি স্টল, প্যাভিলিয়ন ও মিনি প্যাভিলিয়ন রয়েছে।', NULL, 'trade-fair-202301142242091673727537.jpg', NULL, 'অর্থনীতি', 'No', '2023-01-15', '2023-01-15', '02:18AM', NULL, 1, NULL, NULL, '2023-01-15 02:18:56am', NULL, NULL, 'ঢাকা', 'ঢাকা', '', 'আরিফ হোসেন', NULL, '1673727480', 'Noman Abdullah'),
(25, '', 'No', 'No', 'সোনার দাম বেড়ে ভ‌রি ৯৩৪২৯ টাকা', NULL, 'সোনার দাম ভরিতে ২ হাজার ৬৮৩ টাকা বাড়িয়ে নতুন দাম নির্ধারণ করেছে বাংলাদেশ জুয়েলার্স সমিতি (বাজুস)। এতে ভালোমানের প্রতি ভরি সোনার দাম বেড়ে হয়েছে ৯৩ হাজার ৪২৯ টাকা। দেশের বাজারে এটিই সোনার সর্বোচ্চ দাম। এতোদিন ছিল ৯০ হাজার ৭৪৬ টাকা।শনিবার (১৪ জানুয়ারি) বাজুসের মূল্য নির্ধারণ ও মূল্য পর্যবেক্ষণ স্থায়ী কমিটির চেয়ারম্যান এম এ হান্নান আজাদ স্বাক্ষরিত এক সংবাদ বিজ্ঞপ্তিতে এ তথ্য জানানো হয়।ADVERTISEMENTরোববার (১৫ জানুয়ারি) থেকে সোনার এই নতুন দাম কার্যকর করা হবে বলে জানিয়েছে বাজুস। এর আগে সবশেষ গত ৭ জানিুয়া‌রি সোনার দাম ভরিতে বাড়ানো হয় ২ হাজার ৩৩৩ টাকা।নতুন দাম অনুযায়ী, রোববার থেকে ২২ ক্যারেট প্রতি ভরি সোনা কিনতে লাগবে ৯৩ হাজার ৪২৯ টাকা, যা শনিবার পর্যন্ত ছিল ৯০ হাজার ৭৪৬ টাকা, ২১ ক্যারেট প্রতি ভরি সোনার দাম ২৫৬৬ টাকা বা‌ড়ি‌য়ে করা হ‌য়ে‌ছে ৮৯ হাজার ১৭১ টাকা, ১৮ ক্যারেট প্রতি ভরি সোনা কিন‌তে এখন লাগ‌বে ৭৬ হাজার ৪৫৮ টাকা এবং সনাতন পদ্ধতির প্রতি ভরি সোনার দাম ১৪৫৮ টাকা বা‌ড়ি‌য়ে নির্ধারণ করা হ‌য়ে‌ছে ৬৩ হাজার ৩৩৬ টাকা।আ‌গেরবার গত ৭ জানুয়া‌রি সোনার স‌ঙ্গে রূপার দামও বাড়া‌নো হ‌য়ে‌ছিল। ত‌বে এবার রুপার দাম অপরিবর্তিত রাখা হয়েছে। ক্যাটাগরি অনুযায়ী ২২ ক্যারেটের রুপার দাম প্রতি ভ‌রি ১ হাজার ৭১৫ টাকা নির্ধারণ করা হয়েছে। ২১ ক্যারেটের রুপার দাম ১ হাজার ৬৩৩ টাকা, ১৮ ক্যারেটের রুপার দাম ১৪০০ টাকা এবং সনাতন পদ্ধতির রুপার দাম ১০৫০ টাকায় অপরিবর্তিত আছে।ADVERTISEMENTএর আগে সবশেষ ৭ জানুয়া‌রি বাজুস সোনার দাম বাড়ানোর ঘোষণা দেয়। যা ৮ জানুয়া‌রি থেকে কার্যকর হয়। ওই দাম অনুযায়ী আজকে পর্যন্ত সোনা কেনাবেচা হয়েছে ২২ ক্যারেটের প্রতি ভরি ৯০ হাজার ৭৪৬ টাকা, ২১ ক্যারেট প্রতি ভরি সোনা ৮৬ হাজার ৬০৫ টাকা, ১৮ ক্যারেট প্রতি ভরি ৭৪ হাজার ২৪১ টাকা এবং সনাতন পদ্ধতির প্রতি ভরি সোনা বি‌ক্রি হ‌য়ে‌ছে ৬১ হাজার ৮৭৮ টাকা।', NULL, 'gold-price-202301141946571673727608.jpg', NULL, 'অর্থনীতি', 'No', '2023-01-15', '2023-01-15', '02:19AM', NULL, 1, NULL, NULL, '2023-01-15 02:20:07am', NULL, NULL, '', NULL, NULL, 'আরিফ হোসেন', NULL, '1673727540', 'Noman Abdullah'),
(26, '', 'No', 'No', 'বিদ্যুতের মূল্যবৃদ্ধিতে চ্যালেঞ্জের মুখে বেসরকারি খাত', NULL, 'বিদ্যুতের মূল্যবৃদ্ধি দেশের বেসরকারি খাতের জন্য চ্যালেঞ্জিং হতে পারে বলে মনে করে ঢাকা চেম্বার অব কমার্স অ্যান্ড ইন্ডাস্ট্রি (ডিসিসিআই)।শনিবার (১৪ জানুয়ারি) এক প্রতিক্রিয়ায় ঢাকা চেম্বারের সভাপতি ব্যারিস্টার মো. সামীর সাত্তার বলেন, বর্তমানে বৈশ্বিক অর্থনৈতিক সংকট এবং বিপর্যস্ত সাপ্লাই চেইন ব্যবস্থায় অবনতি হওয়ার কারণে বাংলাদেশের অর্থনীতি নানামুখী চ্যালেঞ্জের মধ্য দিয়ে যাচ্ছে। এর মধ্যে অন্যতম প্রধান চ্যালেঞ্জ হচ্ছে, প্রাথমিক জ্বালানি সংকট, যেহেতু আমাদের প্রাথমিক জ্বালানির উৎস মূলত আমদানি নির্ভর। সম্প্রতি খুচরা পর্যায়ে বিদ্যুতের মূল্যবৃদ্ধি বিদ্যুৎ নির্ভর শিল্প কারখানাসহ সামগ্রিক অর্থনৈতিক কর্মকাণ্ড পরিচলনায় অতিরিক্ত ব্যয়ের বোঝা হিসেবে বিবেচিত হবে।ADVERTISEMENTতিনি বলেন, দেশের বেসরকারিখাত উচ্চ মূল্যস্ফীতি এবং টাকার অবমূল্যায়নসহ অন্যান্য অর্থনৈতিক চ্যালেঞ্জের কারণে ইতোমধ্যেই প্রতিকূল অবস্থার মধ্য দিয়ে যাচ্ছে। যদিও আন্তর্জাতিক বাজারে জ্বালানির মূল্যের অস্থিরতার কারণে সরকার এ ধরনের সিদ্ধান্ত নিচ্ছে। সরকার স্থানীয় শিল্প ও বেসরকারি খাতের ওপর যেন বেশি মাত্রায় নেতিবাচক প্রভাব না পড়ে সে বিষয়টি বিবেচনায় নিয়ে বিদ্যুতের মূল্য যৌক্তিকভাবে সমন্বয়ের লক্ষ্যে পরবর্তীতেও কার্যক্রম অব্যাহত রাখবে।&nbsp;ডিসিসিআই বলছে, বাংলাদেশ সরকার প্রতি মাসেই জ্বালানির মূল্য সমন্বয় করার পরিকল্পনা করছে এবং সেই সংক্রান্ত একটি কৌশল নির্ধারণের কাজ চলছে। সরকার যেন বিদ্যুতের মূল্য সহনশীলভাবে এবং ক্রমান্বয়ে বৃদ্ধি করে, যাতে করে বেসরকারিখাত অপ্রত্যাশিত বর্ধিত ব্যয়ের বোঝা এড়াতে পারে। যদিও বিদ্যমান চ্যালেঞ্জ মোকাবিলায় বিদ্যুতের মূল্যবৃদ্ধি করা হয়েছে, তবে চলমান পরিস্থিতি অনুকূলে এলে সরকার যেন পুনরায় এই বর্ধিত মূল্য, হ্রাসের উদ্যোগ গ্রহণ করে। বিষয়টি কোনভাবেই একমুখী হওয়া উচিত হবে না।&nbsp;ব্যারিস্টার সামীর সাত্তার মনে করেন, বর্তমান পরিস্থিতিতে মূল্যবৃদ্ধির হয়তো কোনো বিকল্প নেই। তবুও সরকারের একটি অনুমানযোগ্য মূল্য নির্ধারণ নীতিমালা নিশ্চিত করা প্রয়োজন, যাতে করে এ ধরনের মূল্য বৃদ্ধির কারণে সৃষ্ট প্রভাব সম্পর্কে বেসরকারিখাত আগে থেকেই প্রস্তুতি গ্রহণসহ তাদের ব্যবসা পরিচালনায় কৌশলী সিদ্ধান্ত গ্রহণ করতে পারে। যেহেতু বাংলাদেশ জ্বালানি আমদানির ওপর বেশি মাত্রায় নির্ভরশীল, এমতাবস্থায় নবায়নযোগ্য ও বিকল্প জ্বালানির উৎস খুঁজে বের করতে এবং একই সঙ্গে স্থানীয়ভাবে গ্যাস অনুসন্ধান কার্যক্রমে প্রাধান্য দিতে হবে।&nbsp;ADVERTISEMENTঢাকা চেম্বারের সভাপতি মনে করেন, বিদ্যুৎ খাতে স্বল্পতার সংকট মোকাবিলায় সরকারকে নিয়মিতভাবে সব বিদ্যুৎ কেন্দ্রের সক্ষমতা যাচাই করা এবং সিস্টেম লসকে হ্রাস করার উদ্যোগ গ্রহণ করা উচিত। শিল্প ও বিনিয়োগ খাতে বাংলাদেশের সক্ষমতা ধরে রাখতে নিরবচ্ছিন্ন বিদ্যুৎ ও জ্বালানি অন্যতম গুরুত্বপূর্ণ নিয়ামক হিসেবে ভূমিকা পালন করে। &nbsp;', NULL, 'sattar-202301141644371673727690.jpg', NULL, 'অর্থনীতি', 'No', '2023-01-15', '2023-01-15', '02:20AM', NULL, 1, NULL, NULL, '2023-01-15 02:21:29am', NULL, NULL, 'ঢাকা', '', NULL, 'আরিফ হোসেন', NULL, '1673727600', 'Noman Abdullah'),
(27, '', 'No', 'No', 'পাইকারিতেই ডিমের দাম বেড়েছে ১২০ টাকা ', NULL, 'আবারও বেড়েছে ডিমের দাম। প্রতি ১০০ পিস ডিমের দাম গত সপ্তাহের চেয়ে আজ বেড়েছে ১২০-১৪০ টাকা। তবে অপরিবর্তিত রয়েছে ব্রয়লার মুরগির দাম। গত সপ্তাহের মতো আজও প্রতি কেজি ব্রয়লার মুরগি বিক্রি হচ্ছে ১৪০-১৫০ টাকায়। এছাড়া পাকিস্তানি ব্রয়লার প্রতি কেজি ২২০ টাকা ও দেশি মুরগি প্রতি কেজি ৪০০ টাকা করে বিক্রি হচ্ছে। গত সপ্তাহেও একই দাম ছিল বলে জানিয়েছেন ব্যবসায়ীরা।&nbsp;শুক্রবার (১৩ জানুয়ারি) সকালে রাজধানীর রায়েরবাজার, ধানমন্ডি, মোহাম্মদপুর টাউন হলের বাজার ঘুরে এ তথ্য জানা গেছে।&nbsp;ADVERTISEMENTরাজধানীর রায়ের বাজার সিটি কর্পোরেশন বাজার ঘুরে দেখা গেছে, আজ প্রতি ১০০ পিস ব্রয়লার সাদা ডিম পাইকারি বাজারে ৯২০ টাকায় বিক্রি হচ্ছে। এ হিসেবে পাইকারিতে প্রতি হালির ডিমের দাম ৩৩টা পড়েছে। গত সপ্তাহে এ ডিম বিক্রি হয় প্রতি হালি ৩২ টাকা।&nbsp;আরও পড়ুন :&nbsp;সবজির দাম কিছুটা কম, মাছ-মাংস আগের মতোই চড়াএদিকে ব্রয়লার লাল ডিম ১০০ পিস পাইকারি বাজারে আজ বিক্রি হচ্ছে ৯৬০ টাকায়। সেই হিসেবে প্রতি হালির দাম প্রায় ৩৮ টাকা পড়েছে। গত সপ্তাহে এই ডিমের দাম ছিল ৩২ টাকার মতো। এছাড়া ১০০ পিস হাঁসের ডিমের দাম গত সপ্তাহে ছিল ১৫৫০ টাকা। আজ তা বেড়ে হয়েছে ১৭০০ টাকা। পাইকারি বাজারে ডিমের দামের এ প্রভাব খুচরা বাজারেও পড়বে। তাই গত সপ্তাহের চেয়ে আজ বেশি দামে ডিম কিনতে হবে ক্রেতাদের।&nbsp;', NULL, 'egg-202301130928331673727772.webp', NULL, 'অর্থনীতি', 'No', '2023-01-15', '2023-01-15', '02:21AM', NULL, 1, NULL, NULL, '2023-01-15 02:22:52am', NULL, NULL, '', NULL, NULL, 'আরিফ হোসেন', NULL, '1673727660', 'Noman Abdullah'),
(28, '', 'No', 'No', 'বিকাশ অ্যাপ থেকেই এখন পিন রিসেট', NULL, 'পিন ভুলে গেলে বা কয়েকবার ভুল পিন দেওয়ার কারণে বিকাশ অ্যাকাউন্ট লক হয়ে গেলে গ্রাহকরা এতোদিন ইউএসএসডি কোড *২৪৭# ডায়াল করে নিজেই নিজের অ্যাকাউন্টের পিন রিসেট করতে পারতেন। তবে কাজটি এখন পুরোপুরি বিকাশ অ্যাপ দিয়েই করা যাবে আরো সহজে। সম্প্রতি এই সেবাটি যুক্ত হয়েছে বিকাশ অ্যাপে।নিরাপদ প্রযুক্তির মাধ্যমে অ্যাকাউন্টের সুরক্ষা নিশ্চিত করার পাশাপাশি গ্রাহককে আরো বেশি সক্ষম করে তুলতেই সম্প্রতি বিকাশ অ্যাপে যুক্ত হয়েছে এই সুবিধা।&nbsp;ADVERTISEMENTউল্লেখ্য, বিকাশ অ্যাকাউন্টের সব লেনদেন সম্পন্ন করতে পারসোনাল আইডেন্টিফিকেশন নম্বর (পিন) নম্বর প্রয়োজন। এটি সুরক্ষিত এবং গোপন রেখেই বিকাশ অ্যাকাউন্টের নিরাপত্তা নিশ্চিত করা সম্ভব। বিকাশ গ্রাহকের পিন তিনি নিজেই সেট করে নেন, ফলে একজন গ্রাহকের পিন কেবল তিনিই জানেন এবং কারো পক্ষেই বিকাশ সিস্টেম থেকে ওই পিন জানার কোনো সুযোগ থাকে না। তাই পিন ভুলে গেলে বা লক হয়ে গেলে ঘাবড়ে না গিয়ে গ্রাহক অনায়াসেই সহজ কয়েকটি ধাপে পিন রিসেট করে নিতে পারেন।পিন রিসেট করতে গ্রাহককে বিকাশ অ্যাপে প্রবেশ করে লগ ইন স্ক্রিন থেকে ‘রিসেট পিন’ অপশনে ট্যাপ করতে হবে। পরের ধাপে অনুমতি দিলে মোবাইলে আসা ৬ ডিজিটের অস্থায়ী পিন বা ওটিপি কোড স্বয়ংক্রিয়ভাবে টাইপ হয়ে যাবে। এরপর ‘চেহারা স্ক্যান করুন’ অপশনে ট্যাপ করে নির্দেশনাগুলো সঠিকভাবে অনুসরণ করলে পরের ধাপে ভেরিফিকেশন সম্পন্ন হবে ও অস্থায়ী পিন পাওয়া যাবে। তা দেওয়ার পর শেষ ধাপে গ্রাহক নিজের পছন্দ অনুসারে এলোমেলো পাঁচ সংখ্যার নতুন পিন দিলেই সম্পন্ন হবে পিন রিসেট প্রক্রিয়া।উল্লেখ্য, এই মুহূর্তে আইওএস ব্যবহারকারীরা পিন রিসেট করতে পারছেন *২৪৭# ডায়াল করে। শিগগিরই তারাও বিকাশ অ্যাপ থেকে পিন রিসেট করার সুবিধাটি পাবেন।ADVERTISEMENTইউএসএসডি চ্যানেল দিয়ে পিন রিসেট করাও খুব সহজ। এজন্য *২৪৭# ডায়াল করে ‘রিসেট পিন’ অপশনে সিলেক্ট করতে হবে। পরের ধাপে যে পরিচয়পত্র দিয়ে অ্যাকাউন্ট খোলা হয়েছে সেই নম্বরটি দিতে হবে। এরপর জন্ম সালের চারটি সংখ্যা দিতে হবে। এরপর গ্রাহককে বিগত ৯০ দিনের মধ্যে তার করা শেষ ১০টি ট্রানজেকশনের যেকোনো একটির তথ্য দিতে হবে। আর যদি শেষ ৯০ দিনের মধ্যে কোনো ট্রানজেকশন না করে থাকেন তাহলে ‘নো ট্রানজেকশন’ অপশন নির্বাচন করবেন। গ্রাহকের দেওয়া সব তথ্য ঠিক থাকলে তিনি পাঁচ সংখ্যার অস্থায়ী পিন পেয়ে যাবেন।এরপর আবার *২৪৭# ডায়াল করে ‘মাই বিকাশ’ থেকে ‘চেঞ্জ পিন’ নির্বাচন করতে হবে। পরের ধাপে পুরোনো পিন চাইলে এসএমএস-এ আসা অস্থায়ী পিন নম্বরটি দিতে হবে। এরপর গ্রাহক নিজের পছন্দ অনুসারে পাঁচ সংখ্যার নতুন এলোমেলো পিন দিয়ে আর একবার রিএন্টার করে সফলতার সঙ্গে পিন রিসেট করে নিতে পারবেন।ধাপে ধাপে কিভাবে পিন রিসেট করতে পারবেন তার বিস্তারিত&nbsp;https://www.bkash.com/help/reset-pin&nbsp;- এই লিংকে ক্লিক করে জেনে নিতে পারবেন গ্রাহক।', NULL, 'pin-bg-202301130304121673727830.jpg', NULL, 'অর্থনীতি', 'No', '2023-01-15', '2023-01-15', '02:22AM', NULL, 1, NULL, NULL, '2023-01-15 02:23:50am', NULL, NULL, '', NULL, NULL, 'আরিফ হোসেন', NULL, '1673727720', 'Noman Abdullah'),
(29, '', 'No', 'No', 'বাংলাদেশের অর্থনীতিতে পাঁচ ঝুঁকি দেখছে ডব্লিউইএফ', NULL, 'বাংলাদেশের অর্থনীতিতে পাঁচটি ঝুঁকি দেখছে ওয়ার্ল্ড ইকোনমিক ফোরাম (ডব্লিউইএফ)। এ ঝুঁকিগুলো হলো- উচ্চ মূল্যস্ফীতি, ঋণসংকট, উচ্চ পণ্যমূল্যের ধাক্কা, মানবসৃষ্ট পরিবেশগত ক্ষতি ও সম্পদের জন্য ভূরাজনৈতিক প্রতিযোগিতা।&nbsp;ডব্লিউইএফের ধারণাগত এই জরিপে মোট ৩৫টি ঝুঁকির কথা বলা হয়। জরিপে অংশগ্রহণকারীদের শীর্ষ পাঁচটি ঝুঁকি চিহ্নিত করতে বলা হলে তারা ক্রমানুসারে ওই পাাঁচটি ঝুঁকি চিহ্নিত করেন। বাংলাদেশের মোট ৭২টি কোম্পানি জরিপে অংশ নেয়। &nbsp;ADVERTISEMENTঅন্যান্য দেশেও তারা এই জরিপ করেছে। তাদেরও শীর্ষ পাঁচটি ঝুঁকি চিহ্নিত করতে বলা হয়। সার্বিক জরিপ থেকে তারা সারা বিশ্বে আগামী দুই বছরের অর্থনৈতিক ঝুঁকি চিহ্নিত করেছে। জরিপের ফলাফল থেকে তারা বলছে, বিশ্ব অর্থনীতি মন্দার কাছাকাছি পৌঁছে গেছে। &nbsp;বাংলাদেশে ডব্লিউইএফের অংশীদার হিসেবে কাজ করেছে সেন্টার ফর পলিসি ডায়ালগ (সিপিডি)।&nbsp;', NULL, '1007-202301141001471673727921.jpg', NULL, 'অর্থনীতি', 'No', '2023-01-15', '2023-01-15', '02:24AM', NULL, 1, NULL, NULL, '2023-01-15 02:25:20am', NULL, NULL, '', NULL, NULL, 'আরিফ হোসেন', NULL, '1673727840', 'Noman Abdullah'),
(30, '', 'No', 'No', 'টয়োটা মিরাই : প্রতি কিমিতে খরচ মাত্র এক টাকা!', NULL, 'টয়োটার নতুন মডেল মিরাই প্রদর্শন করেছে জাপানি গাড়ি নির্মাণকারী প্রতিষ্ঠান টয়োটা মোটর কর্পোরেশন। নতুন মডেলের এই গাড়ির বিশেষত্ব হলো- এটি হাইড্রোজেন ফুয়েল সেলে চালিত। ৬৪০ কিলোমিটার রেঞ্জ দেবে এ গাড়িটি। এই প্রযুক্তিতে প্রতি কিলোমিটার গাড়ি চালাতে মাত্র ১ টাকার জ্বালানি খরচ হবে।বিভিন্ন সংবাদমাধ্যমের প্রতিবেদনে এমনটাই উল্লেখ করা হয়েছে।ADVERTISEMENTমিরাইয়ের বৈদ্যুতিক মোটর ১৮২ বিএইচপি পাওয়ার এবং ৩০০ এনএম পিক টর্ক জেনারেট করে। বৈদ্যুতিক মোটরের মাধ্যমে গাড়িটি ৯.২ সেকেন্ডে ০-১০০ কেএমপিএইচ গতিবেগ তুলতে সক্ষম।ভারতে হাইড্রোজেন গাড়ির পাইলট প্রোজেক্ট হিসেবে টয়োটা মিরাইকে চালু করা হতে পারে। গাড়িটি দেখতেও নিঃসন্দেহে দুর্দান্ত।&nbsp;এর আগে গত বছরের শুরুতেই এই গাড়ি ভারতে আনার বিষয়ে জানিয়েছিল টয়োটা। কেন্দ্রীয় পরিবহণমন্ত্রী নীতিন গড়করি ভারতে গাড়ির পর্দা উন্মোচন করেছিলেন।', NULL, 'toyota-202301142221121673728087.jpg', NULL, 'আন্তর্জাতিক', 'No', '2023-01-15', '2023-01-15', '02:26AM', NULL, 1, NULL, NULL, '2023-01-15 02:28:07am', NULL, NULL, '', NULL, NULL, 'আরিফ হোসেন', NULL, '1673727960', 'Noman Abdullah');
INSERT INTO `tbl_news` (`id`, `sironam_status`, `homepage_status`, `highlight_status`, `title_bn`, `title_en`, `detail_bn`, `detail_en`, `image`, `viewers`, `categoryid`, `top_news`, `date`, `publish_date`, `publish_time`, `archieve_date`, `created_by`, `update_by`, `deleted_by`, `created_at`, `updated_at`, `deleted_at`, `Division`, `District`, `Upozila`, `ReporterName`, `VideoLink`, `news_live_time`, `i_user`) VALUES
(31, '', 'No', 'No', 'প্রেসিডেন্টসহ এনডিটিভির উচ্চপদস্থ কর্মকর্তাদের পদত্যাগ', NULL, 'ভারতের স্বাধীন ও জনপ্রিয় গণমাধ্যম নিউ দিল্লি টেলিভিশনের (এনডিটিভি) প্রেসিডেন্ট সুপর্ণা শর্মাসহ অন্যান্য উচ্চপদস্থ কর্মকর্তারা পদত্যাগ করেছেন।ব্রিটিশ বার্তাসংস্থা রয়টার্স জানিয়েছে, শুক্রবার বড় কর্তারা একযোগে পদত্যাগ করেন।ADVERTISEMENTভারতের সবচেয়ে বড় শিল্প গোষ্ঠী আদানি গ্রুপ এনডিটিভির ৬৫ ভাগ নিয়ন্ত্রণ নেওয়ার পর দায়িত্বশীল অনেকে সরে যাচ্ছেন।এনডিটিভির চিফ স্ট্র্যাটেজিক অফিসার (সিএসও) অরজিৎ চ্যাটার্জি, চিফ টেকনোলজি অ্যান্ড প্রডাক্ট অফিসার কাওয়ালজিৎ সিং বেদিও পদত্যাগ করেছেন। এনডিটিভির প্রতিষ্ঠাতা প্রণয় রায় এবং রাধিকা রায় গত বছরের ডিসেম্বরে দায়িত্ব ছেড়ে দেন।ধনকুবের গৌতম আদানির নেতৃত্বাধীন আদানি গ্রুপ প্রথমে এনডিটিভির মালিকানা কেনার চেষ্টা চালায়। কিন্তু এতে ব্যর্থ হয়ে তারা প্রতিষ্ঠানটির অধিকাংশ শেয়ার কিনে এর নিয়ন্ত্রণ নেয়।', NULL, 'unnamed-202301141711401673728162.webp', NULL, 'আন্তর্জাতিক', 'No', '2023-01-15', '2023-01-15', '02:28AM', NULL, 1, NULL, NULL, '2023-01-15 02:29:21am', NULL, NULL, '', NULL, NULL, 'আরিফ হোসেন', NULL, '1673728080', 'Noman Abdullah'),
(32, '', 'No', 'No', '‘সব প্রকাশ করলে পরিবার কখনো ক্ষমা করত না’, বললেন প্রিন্স হ্যারি', NULL, '‘স্পেয়ার’ নামে একটি স্মৃতিকথামূলক বই প্রকাশ করে চারদিকে হইচই ফেলে দিয়েছেন যুক্তরাজ্যের প্রিন্স হ্যারি। এই বইয়ে নিজেদের জীবনের বিভিন্ন দিক তুলে ধরেছেন তিনি।এরমধ্যে রয়েছে নিজের আপন ভাই প্রিন্স উইলিয়ামের সঙ্গে মারামারি হওয়ার ঘটনা, বাবাকে আবারও বিয়ে না করতে বলা এবং আফগানিস্তানে কথিত অভিযানে ২৫ জন তালেবান যোদ্ধাকে হত্যার কথা। এই স্মৃতিকথায় মূলত নিজ স্ত্রী মেগান মের্কেলকে নিয়ে পরিবারের সঙ্গে হওয়া বিভিন্ন ঝামেলার কথা তুলে ধরেছেন হ্যারি।ADVERTISEMENTতবে প্রিন্স হ্যারি জানিয়েছেন, তার ভাই ও বাবার সঙ্গে আরও অনেক কিছু নিয়ে তার ঝামেলা হয়েছে। কিন্তু সেগুলো তিনি বইয়ে উল্লেখ করেননি। যদি করতেন তাহলে তার পরিবার হয়ত তাকে কখনোই ক্ষমা করত না।ব্রিটিশ সংবাদমাধ্যম ডেইলি টেলিগ্রাফের সাংবাদিক ব্রায়োনি গর্ডনের সঙ্গে দেওয়া এক সাক্ষাৎকারে এমন মন্তব্য করেছেন হ্যারি। তিনি আরও জানিয়েছেন, তিনি চান তার পরিবারের সদস্যরা যেন স্ত্রী মেগান মের্কেলের কাছে ক্ষমা চান।সাংবাদিক ব্রায়োনি গর্ডন প্রিন্স হ্যারির সঙ্গে দেখা করতে যুক্তরাষ্ট্রের ক্যালিফোর্নিয়াতে গিয়েছিলেন। সাক্ষাৎকারে হ্যারি দাবি করেছেন, তিনি ‘রাজতন্ত্রের পতন ঘটাতে’ এসব করছেন না। এর বদলে ‘তাদের জন্যই তাদের বাঁচাতে চাইছেন।’ADVERTISEMENTপ্রিন্স হ্যারির কাছে বর্ণনা শুনে বইটি লিখেছেন নেপথ্য লেখক জেপি মরিঙ্গার। হ্যারি জানিয়েছেন মরিঙ্গারের কাছে অনেক কথা বলেছেন তিনি। কিন্তু সেগুলো মূল বইয়ে তুলে ধরা হয়নি। ওই সব কিছু উল্লেখ করলে দু’টি বই প্রকাশ করা যেত। বইয়ের প্রথম ড্রাফটটি ৮০০ পাতার হয়েছিল। যা কমিয়ে ৪০০ পাতায় নিয়ে আসা হয়।এ ব্যাপারে হ্যারি বলেছেন, ‘পরিবারের সদস্যদের বিষয়টি না আনলে আমি আমার জীবন সম্পর্কে কিছুই বলতে পারতাম না। তারাই আমার জীবনে সবচেয়ে বেশি প্রভাব রেখেছেন। এছাড়া বইয়ে উল্লেখিত সবার সম্পর্কেও আপনাকে বুঝতে হবে।’তিনি আরও বলেছেন, ‘কিন্তু এমন কিছু ঘটনা ঘটেছে। বিশেষ করে আমার ভাই ও বাবার মধ্যে, যেগুলো আমি চাই না পৃথিবীর মানুষ জানুক। আমি মনে করি এগুলো প্রকাশ করলে তারা কখনো আমাকে ক্ষমা করতেন না। কিন্তু এখন আপনারা বলতে পারেন তাদের নিয়ে কিছু বিষয় প্রকাশিত হয়েছে। ঠিক আছে, তারা এমনিতেও আমাকে কখনো ক্ষমা করবে না।’এরপর পরিবারের সদস্যদের নিজের সঙ্গে বসার আহ্বান জানিয়েছেন প্রিন্স হ্যারি। তিনি বলেছেন, ‘কিন্তু আমি যেভাবে দেখি। আপনারা আমার সঙ্গে যাই করেছেন আমি আপনাদের ক্ষমা করে দেব। আমি আশা করি, আমি ভুলভালে আছি এগুলো না বলে, আপনারা আমার সঙ্গে ভালোভাবে বসবেন। আসলে আমার সঙ্গে ভালোভাবে বসুন। আমি যেটি চাই সেটি হলো দায় নেওয়া এবং আমার স্ত্রীর কাছে ক্ষমা চাওয়া।সূত্র: বিবিসি', NULL, 'harry-potter-202301141900281673728314.jpg', NULL, 'আন্তর্জাতিক', 'No', '2023-01-15', '2023-01-15', '02:31AM', NULL, 1, NULL, NULL, '2023-01-15 02:31:53am', NULL, NULL, '', NULL, NULL, 'আরিফ হোসেন', NULL, '1673728260', 'Noman Abdullah'),
(33, '', 'Yes', 'Yes', 'কিয়েভে নতুন করে হামলা চালিয়েছে রাশিয়া', NULL, 'ইউক্রেনের রাজধানী কিয়েভের গুরুত্বপূর্ণ স্থাপনায় হামলা চালিয়েছে রুশ সেনারা। গত কয়েকদিন হামলা বন্ধ রাখার পর আবারও শনিবার রাজধানী লক্ষ্য করে রকেট ছুড়েছে তারা।ব্রিটিশ সংবাদমাধ্যম দ্য গার্ডিয়ান শনিবার (১৪ জানুয়ারি) এক প্রতিবেদনে এ তথ্য জানিয়েছে।ADVERTISEMENTগার্ডিয়ানের দেওয়া তথ্য অনুযায়ী, শনিবার সকালে কিয়েভে চারটি বিস্ফোরণের শব্দ শোনা যায়।কিয়েভের মেয়র ভিটালি ক্লিটসকো নতুন হামলার বিষয়টি নিশ্চিত করেছেন। টেলিগ্রামে তিনি জানিয়েছেন, কিয়েভের দিনিপ্রোভস্কি বিভাগের পশ্চিম তীরে বিস্ফোরণের ঘটনা ঘটেছে। হামলাস্থলে এখন জরুরি পরিষেবার কর্মীরা যাচ্ছেন।বিস্ফোরণের শব্দ শোনার কয়েক মিনিট পর ইউক্রেনের প্রেসিডেন্ট দপ্তরের প্রধান প্রশাসনিক কর্মকর্তা কাইরাইলো তায়মোশেঙ্কো টেলিগ্রামে জানান, রাজধানী কিয়েভের গুরুত্বপূর্ণ অবকাঠামোর ওপর হামলা হয়েছে। তিনি সাধারণ মানুষকে নিরাপদ স্থানে আশ্রয় নেওয়ার অনুরোধ জানান।ADVERTISEMENTকিয়েভ অঞ্চলের গভর্নর ওলেক্সি কুলেবা জানিয়েছেন, হামলায় ১৮টি আবাসিক ভবন ক্ষতিগ্রস্থ হয়েছে। তবে এখন পর্যন্ত কোনো হতাহতের খবর পাওয়া যায়নি। তিনি আরও জানিয়েছেন, ‘গুরুত্বপূর্ণ অবকাঠামোয়’ লাগা আগুন নিয়ন্ত্রণে আনা হয়েছে।কাতারভিত্তিক সংবাদমাধ্যম আল জাজিরা জানিয়েছে, শনিবার কিয়েভ ছাড়াও ইউক্রেনের দ্বিতীয় বৃহৎ শহর খারকিভে ক্ষেপণাস্ত্র ছুড়েছে রাশিয়া। খারকিভের গভর্নর ওলেহ সাইনিহুভোভ বলেছেন, রুশ সেনারা বাণিজ্যিক অঞ্চল লক্ষ্য করে দু’টি এস-৩০০ ক্ষেপণাস্ত্র ছুড়েছে।অপরদিকে দক্ষিণ দিকের অঞ্চল মাইকোলাইভের গভর্নর ভিতালি কিম জানিয়েছেন, শনিবার রাশিয়ার ১৭টি তুপোলেভ বোম্বার বিমান আকাশে উড়েছে। যেগুলো ইউক্রেনজুড়ে আরও বড় হামলা চালাতে পারে।সূত্র: দ্য গার্ডিয়ান, আল জাজিরা', NULL, 'russia-attack-fuk-202301141629571673728393.jpg', '2', 'আন্তর্জাতিক', 'No', '2023-01-15', '2023-01-15', '02:32AM', NULL, 1, NULL, NULL, '2023-01-15 02:33:13am', NULL, NULL, '', NULL, NULL, 'আরিফ হোসেন', NULL, '1673728320', 'Noman Abdullah'),
(34, '', 'No', 'No', 'রাস্তায় লুটিয়ে পড়ে কংগ্রেস এমপির আকস্মিক মৃত্যু', NULL, 'ভারতের বিরোধীদল কংগ্রেসের ভারত জোড়ো যাত্রা চলাকালীন এক এমপির আকস্মিক মৃত্যু হয়েছে। ওই এমপির নাম সান্তোক সিং চৌধুরী। তার বয়স ছিল ৭৬ বছর।ভারতীয় সংবাদমাধ্যম এনডিটিভি শনিবার (১৪ জানুয়ারি) এক প্রতিবেদনে এ তথ্য জানিয়েছে।ADVERTISEMENTশনিবার সকালে পাঞ্জাব প্রদেশের ফিল্লুর নামক একটি স্থানে চলছিল রাহুল গান্ধীর নেতৃত্বাধীন ভারত জোড়ো যাত্রার কর্মসূচি। ওই সময় সান্তোক সিং চৌধুরী মাটিতে লুটিয়ে পড়েন। তাকে দ্রুত অ্যাম্বুলেন্সে করে পাগওয়ারার একটি হাসপাতালে নিয়ে যাওয়া হয়। সেখানে তাকে মৃত ঘোষণা করা হয়। সান্তোক সিং জালান্দারের এমপি ছিলেন।সংবাদমাধ্যম এনডিটিভি আরও জানিয়েছে, সান্তোক সিংকে হাসপাতালে নেওয়ার পর ভারত জড়ো যাত্রা থামিয়ে সেখানে ছুটে যান রাহুল গান্ধী। আজকের জন্য এই যাত্রার কার্যক্রম পুরোপুরি স্থগিত করা হয়।কিছুক্ষণবাদে সামাজিক যোগাযোগমাধ্যমে কয়েকটি ছবি প্রকাশ করেন রাহুল গান্ধী। সেখানে দেখা যায়, সকালেও সান্তোক সিং চৌধুরী তার সঙ্গে একই সঙ্গে ভারত জোড়ো যাত্রায় হাঁটছেন।', NULL, 'ani-20230114042958-202301141446201673728464.jpg', NULL, 'আন্তর্জাতিক', 'No', '2023-01-15', '2023-01-15', '02:33AM', NULL, 1, NULL, NULL, '2023-01-15 02:34:23am', NULL, NULL, '', NULL, NULL, 'আরিফ হোসেন', NULL, '1673728380', 'Noman Abdullah'),
(35, '', 'Yes', 'No', 'শেখ কামাল গেমসের বিভাগীয় পর্ব ১৬ জানুয়ারি ', NULL, 'দেশব্যাপী চলছে শেখ কামাল যুব গেমস। তৃণমূল পর্যায় থেকে শুরু হওয়া এই গেমস নিয়ে সাড়া পড়েছে বেশ। ১৬ জানুয়ারি থেকে বিভাগীয় পর্যায়ে শুরু হচ্ছে গেমস। ‘বুকে হাত রেখে, বিজয়ের বেশে ছুঁয়ে দেব আসমান’ স্লোগান নিয়ে ১৬ জানুয়ারি থেকে শুরু হতে যাচ্ছে টুর্নামেন্টের চট্টগ্রাম বিভাগীয় পর্ব। ১৬-২২ জানুয়ারি চট্টগ্রামে এই প্রতিযোগিতা অনুষ্ঠিত হবে। যেখানে চট্টগ্রাম বিভাগীয় পর্বে অংশগ্রহণ করবে প্রায় ৭০০ জন তরুণ-তরুণী। চট্টগ্রাম বিভাগের অধীনস্থ ১১টি জেলার উদীয়মান যুব ক্রীড়াবিদরা সর্ববৃহৎ এ আসরে অংশ নেওয়ার সুযোগ পাচ্ছেন। \r\n১৬ জানুয়ারি এমএ আজিজ স্টেডিয়ামে হবে অ্যাথলেটিক্স। ঐ দিনই সাগরিকা মহিলা ক্রীড়া কমপ্লেক্সে হ্যান্ডবল অনুষ্ঠিত হবে। ১৭-১৯ জানুয়ারি ফেনীর ভাষা শহীদ আব্দুস সালাম স্টেডিয়ামে ফুটবল অনুষ্ঠিত হবে। সাগরিকা মহিলা ক্রীড়া কমপ্লেক্সে ১৭-১৮ এই দুই দিন কাবাডি অনুষ্ঠিত হবে। এমএ আজিজ স্টেডিয়ামে ২০ জানুয়ারি তায়কোয়ান্দো, ১৯-২০ জানুয়ারি বান্দরবান জেলা জিমনেসিয়ামে কারাতে, ১৯-২১ জানুয়ারি এমএ আজিজ স্টেডিয়ামে দাবা ও ব্যাডমিন্টন অনুষ্ঠিত হবে। \r\nADVERTISEMENT\r\nপ্রতিযোগিতার প্রতিটি ইভেন্টে প্রথম স্থান অধিকারী ক্রীড়াবিদ ১৫০০ টাকা এবং ২য় স্থান অধিকারী ক্রীড়াবিদ ১০০০ টাকা করে পাবেন। আন্তঃজেলা প্রতিযোগিতা শেষে ২৪টি ইভেন্টে বাছাই প্রক্রিয়ার মাধ্যমে বিভাগীয় দল গঠন করা হবে। অনুশীলনের মাধ্যমে তারা আগামী ২৬ ফেব্রুয়ারি শুরু হতে যাওয়া চূড়ান্ত পর্বে অংশগ্রহণ করবে।  \r\nআজ সংবাদ সম্মেলনে চট্টগ্রাম বিভাগীয় ক্রীড়া সংস্থা গেমসের বিভাগীয় আয়োজন সম্পর্কে নিজেদের অবস্থান তুলে ধরে। এসময় চট্টগ্রাম বিভাগীয় ক্রীড়া সংস্থার সাধারণ সম্পাদক সিরাজউদ্দিন মোঃ আলমগীর সহ অন্য কর্মকর্তারা উপস্থিত ছিলেন। জাতির জনক বঙ্গবন্ধু শেখ মুজিবুর রহমানের জ্যেষ্ঠ পুত্র শেখ কামালের নামে এবারের আসরের নামকরণ করা হয়েছে ‘শেখ কামাল ২য় বাংলাদেশ যুব গেমস ২০২৩’। ২০১৮ সালে প্রথমবার যুব গেমস আয়োজন করেছিল বাংলাদেশ অলিম্পিক এসোসিয়েশন।  ', NULL, 'bpl-21-202301142246211673728581.webp', NULL, 'খেলা', 'No', '2023-01-15', '2023-01-15', '02:34AM', NULL, 1, NULL, NULL, '2023-01-15 02:36:21am', NULL, NULL, '', NULL, NULL, 'আরিফ হোসেন', NULL, '1673728440', 'Noman Abdullah'),
(36, '', 'No', 'No', 'বিদেশি রেফারি বিশেষজ্ঞ নিয়োগ বাফুফের', NULL, 'ঘরোয়া ক্রীড়াঙ্গনে রেফারিং, আম্পায়ারিং নিয়ে অভিযোগ বিস্তর। বিশেষ করে গত ফুটবল মৌসুমে রেফারিং নিয়ে অনেক আলোচনা-সমালোচনা হয়েছে। রেফারিংয়ের মান উন্নয়নের জন্য বাফুফে ভারত থেকে রেফারিং বিশেষজ্ঞ নিয়োগ দিয়েছে।ভারতের সাবেক ফিফা রেফারি গৌতম করের সঙ্গে ২ বছরের জন্য চুক্তি করেছে বাফুফে। এই সময়ের মধ্যে তিনি বাংলাদেশের রেফারিং নিয়ে সামগ্রিকভাবে কাজ করবেন। ভারতীয় এই রেফারি এর আগে ভারত, নেপাল, ভূটানের রেফারিজ ডাইরেক্টর ছিলেন।&nbsp;ADVERTISEMENTআজ বিকেলে বাফুফে সভাপতি কাজী সালাউদ্দিনের সঙ্গে সৌজন্য সাক্ষাৎ করেছেন ভারতের সাবেক ফিফা রেফারি। বাংলাদেশের রেফারিং উন্নয়নের ব্যাপারে আশাবাদ ব্যক্ত করে তিনি বলেন, ‘আমি রেফারিজ বিভাগে বেশি ফোকাস করতে চাই এর মাধ্যমে বাংলাদেশে গুণগত ও সংখ্যাগত রেফারির বহিঃপ্রকাশ ঘটবে ভবিষ্যতে।’&nbsp;রেফারিজ বিভাগে হেড অফ রেফারিজ হিসেবে কাজ করছেন বাংলাদেশের সাবেক ফিফা রেফারি আজাদ রহমান। ঢাকা বিশ্ববিদ্যালয়ের শারীরিক শিক্ষা বিভাগের এই কর্মকর্তার মাধ্যমেই মূলত বাংলাদেশের রেফারিংয়ের বিভিন্ন বিষয় তিনি ভালোমতো জানবেন। রেফারি এসেসর, ম্যাচ কমিশনার হিসেবে বেশ কয়েকবার বাংলাদেশ সফর করেছিলেন গৌতম। বাংলাদেশের ফুটবল সম্পর্কে খানিকটা ধারণা রয়েছে এই রেফারি বিশেষজ্ঞের।', NULL, 'bff-1-202301142114461673728655.webp', NULL, 'খেলা', 'No', '2023-01-15', '2023-01-15', '02:36AM', NULL, 1, NULL, NULL, '2023-01-15 02:37:34am', NULL, NULL, '', NULL, NULL, 'আরিফ হোসেন', NULL, '1673728560', 'Noman Abdullah'),
(37, '', 'No', 'No', 'দলকে চট্টগ্রামে রেখে ঢাকায় সাকিব', NULL, 'ডিসেম্বর মাসে সাকিব আল হাসানের স্ত্রী-সন্তানরা ছিলেন বাংলাদেশে। সামাজিক যোগাযোগ মাধ্যমে সে সময়ে তাদের বিভিন্ন ছবিও ভেসে বেড়িয়েছে। বিপিএলেও ঢাকা পর্বের এক ম্যাচে সাকিবের দল ফরচুন বরিশালের খেলা মাঠে এসে দেখেছেন স্ত্রী উম্মে আহমেদ শিশির।&nbsp;সন্তানদের নিয়ে সাকিব পত্নী আবার দেশ ছাড়তে যাচ্ছেন। ঢাকা থেকে সরাসরি পাড়ি জমাবেন যুক্তরাষ্ট্রে। আর পরিবারকে বিদায় দিতে শনিবার কুমিল্লা ভিক্টোরিয়ান্সের বিপক্ষে ম্যাচ জয়ের পর তড়িঘড়ি করে ঢাকার ফ্লাইট ধরেছেন সাকিব আল হাসান। টিম ম্যানেজমেন্টের পক্ষ থেকে বিষয়টি নিশ্চিত করা হয়েছে ঢাকা পোস্টকে।ADVERTISEMENTসাকিব অবশ্য দলের অনুমতি নিয়েই ঢাকায় গেছেন। আর আগামী তিন দিনে তার দল ফরচুন বরিশালের কোনো খেলাও নেই। বিশ্বসেরা এই অলরাউন্ডারের পরিবার যুক্তরাষ্ট্রে উড়াল দেওয়ার পরই আবারো চট্টগ্রামে দলের সঙ্গে যোগ দেওয়ার কথা রয়েছে তার।&nbsp;চলতি বিপিএলে সাকিব মাঠের পারফরম্যান্সে নজর কেড়ে চলেছেন প্রতি ম্যাচে। কুমিল্লা ভিক্টোরিয়ান্সের বিপক্ষে আজকের ম্যাচেও খেলেছেন দুর্দান্ত। ব্যাট হাতে ৮ চার ও ৪ ছক্কায় করেন ৮১ রান। বল খেলেছেন মোটে ৪৫টি। এছাড়া বল হাতেও দেখিয়েছেন ঝলক। ৩ ওভার হাত ঘুরিয়ে নিয়েছেন ১ উইকেট।', NULL, 'bpl-18-202301142140591673728713.webp', NULL, 'খেলা', 'No', '2023-01-15', '2023-01-15', '02:37AM', NULL, 1, NULL, NULL, '2023-01-15 02:38:32am', NULL, NULL, 'চট্টগ্রাম', 'চট্টগ্রাম', '', 'আরিফ হোসেন', NULL, '1673728620', 'Noman Abdullah'),
(38, '', 'No', 'No', 'রুদ্ধশ্বাস ম্যাচে শেষ হাসি সাকিবের বরিশালের', NULL, 'পুরো ম্যাচে প্রতিদ্বন্দ্বিতা হয়েছে বেশ। বড় লক্ষ্য তাড়ার লড়াইয়ে কখনো বরিশাল এগিয়েছে কখনো কুমিল্লা। তবে চাপ ধরে রেখে শেষ হাসি হেসেছে ফরচুন বরিশাল। রুদ্ধশ্বাস লড়াইয়ে কুমিল্লা ভিক্টোরিয়ান্সকে ১২রানে হারিয়েছে সাকিব আল হাসানের দল।&nbsp;চট্টগ্রামের জহুর আহমেদ চৌধুরি স্টেডিয়ামে শনিবার কুমিল্লা ভিক্টোরিয়ান্সকে ১৭৮ রানের লক্ষ্য দিয়েছিল বরিশাল। বড় লক্ষ্যে শুরুটা ভালোই করেছিল কুমিল্লার দুই ওপেনার লিটন দাস ও মোহাম্মদ রিজওয়ান। ৪২ রান আসে উদ্বোধনী জুটি থেকে। ১১ বলে ১৮ রান করে রিজওয়ান ফেরেন কামরুল ইসলাম রাব্বির বলে।&nbsp;ADVERTISEMENTভালো শুরু পেয়েও কাজে লাগাতে পারেননি লিটন। ৩২ রান করে আউট হয়েছেন দুর্ভাগ্যজনকভাবে রান আউট হয়ে। তবে আশা জাগিয়েছিল মিডল অর্ডার। অধিনায়ক ইমরুল কায়েসের ১৫ বলে ২৮ রান লড়াইয়ে ফেরত আনে তার দলকে। কিন্তু সময়মতো ইমরুলকে সাজঘরে ফেরান চতুরঙ্গ ডি সিলভা।&nbsp;শেষদিকে খুশদিল শাহ এবং মোসাদ্দেক হোসেনের ৫৪ রানের জুটি প্রতিদ্বন্দ্বিতাকে আরও কঠিন করে তোলে। শেষ ৯ বলে ২৪ দরকার ছিল কুমিল্লার। দুইজনই ছিলেন সেট ব্যাটার। এমন সময় মোসাদ্দেককে বোল্ড করেন করিম জানাত। এরপর আর লড়াইয়ে থাকতে পারেনি কুমিল্লা। ১৬৫ রানে থামে কুমিল্লার ইনিংস।&nbsp;এর আগে প্রথম ইনিংসে সাকিব আল হাসানের ঝোড়ো ব্যাটিংয়ে ১৭৭ রানের বড় সংগ্রহ পায় বরিশাল। তবে শুরুটা ভালো হয়নি বরিশালের। মেহেদী হাসান মিরাজ। ফিরে যান মাত্র ৬ রান করে। আরেক ওপেনার এনামুল হক বিজয়ও থিতু হয়েও পারেননি ইনিংস বড় করতে ফিরেছেন ২০ রান করে। তিনে নামা চতুরঙ্গ ডি সিলভা ভালো শুরুর আভাস দিয়েও ফিরেছেন ২১ রান করে। পরবর্তীতে দলের হার ধরেন অধিনায়ক সাকিব।', NULL, 'shakib-37-202301141658191673728780.webp', NULL, 'খেলা', 'No', '2023-01-15', '2023-01-15', '02:39AM', NULL, 1, NULL, NULL, '2023-01-15 02:39:39am', NULL, NULL, 'বরিশাল', 'বরিশাল', '', 'আরিফ হোসেন', NULL, '1673728740', 'Noman Abdullah'),
(39, '', 'No', 'No', '‘সামান্য জুতাটাও এদের সামনে এনে রাখতে হয়’', NULL, 'তারকা সন্তান বলে বরাবরই তাদের জীবনযাত্রা একটু আয়েশি স্বভাবের হয়। হুকুম তামিল করার জন্য বাবা-মায়েরা আলাদা লোক রাখেন। কষ্ট যাতে তাদের সন্তানদের না স্পর্শ করে সেই চেষ্টা থাকে সর্বদা। বলিউড অভিনেতা অনিল কাপুরের মেয়ে সোনম কাপুরও ব্যতিক্রম নন। সম্প্রতি তার জুতা এগিয়ে দিতে দেখা গেল একজনকে। আর তা নিয়েই নেটিজেনদের তোপের মুখে পড়লেন সোনম। &nbsp;শনিবার (১৪ জানুয়ারি) সোশ্যাল মিডিয়ায় সোনম কাপুরের একটি ভিডিও ভাইরাল হয়েছে। যেখানে দেখা যাচ্ছে, যোগা ক্লাস থেকে বের হচ্ছেন অনিল-কন্যা। অল ব্ল্যাক আউটফিট, খোলা চুলে বরাবরের মতোই ফ্যাশনিস্তা তিনি। তবে বিপত্তি বাধল যখন দেখা গেল সঙ্গে থাকা এক ব্যক্তি স্লিপার নিয়ে রাখল সোনমের পায়ের কাছে। আর তাতে পা গলালেন অভিনেত্রী। সোনমের এহেন কীর্তিকে ক্ষমাহীন চোখেই দেখল সোশ্যাল মিডিয়া।ADVERTISEMENTএক ব্যক্তি কমেন্ট সেকশনে লিখেছেন, ‘আজকালকার জেনারেশনের কাছে এত টাকা হয়ে গেছে যে কাকে কী কাজে লাগাবে বুঝতে পারে না। সামান্য জুতাটাও এদের সামনে এনে রাখতে হয়।’ অপরজন লিখলেন, ‘জঘন্য! গাড়ির দরজা খোলানো, মাথায় ছাতা ধরানো অবধি ঠিক ছিল। এটা বাড়াবাড়ি হয়ে গেল।’ তৃতীয়জনের মত, ‘কাপুর পরিবারের ঔদ্ধত্য বরাবরই বেশি। আজকের জেনারেশনও তা পদে পদে প্রমাণ করছে।’জুতা নিয়ে রাখা হচ্ছে সোনমের সামনেগত বছরের আগস্ট মাসে সোনম কাপুর অবং আনন্দ আহুজার ঘরে পুত্র সন্তানের জন্ম হয়। ছেলের নাম রেখেছেন বায়ু। ডেলিভারির মাসখানেক আগে লন্ডনের নটিং হিল থেকে মুম্বাইতে এসেছিলেন অভিনেত্রী। আপাতত মুম্বাইতে রয়েছেন। প্রসবকালীন ওজন কমানোর জন্য চলছে কঠোর পরিশ্রম। এদিনও যোগা ক্লাস থেকে বের হওয়ার সময়ই ভিডিওটি ভাইরাল হয়।প্রসঙ্গত, ২০১৮ সালের ৮ মে বিয়ে করেন সোনম ও আনন্দ। বিয়ের পর থেকেই বড় পর্দায় কাজ কমিয়ে দেন তিনি। সোনমকে সর্বশেষ বড় পর্দায় দেখা গেছে ‘একে ভার্সেস একে’ ছবিতে, ২০২০ সালে। সামনে সোম মাখিজার ‘ব্লাইন্ড’-এ দেখা যাবে তাকে।', NULL, 'sonam-shoe-202301142114331673728868.jpg', NULL, 'বিনোদন', 'No', '2023-01-15', '2023-01-15', '02:40AM', NULL, 1, NULL, NULL, '2023-01-15 02:41:07am', NULL, NULL, '', NULL, NULL, 'আরিফ হোসেন', NULL, '1673728800', 'Noman Abdullah'),
(40, '', 'No', 'No', 'ভক্তদের আবদার মেটাতে ‘সিক্স প্যাক’ দেখালেন শুভ', NULL, 'ঢালিউডের জনপ্রিয় অভিনেতা আরিফিন শুভ বরাবরই চরিত্রের প্রয়োজনে নিজেকে প্রস্তুত করে থাকেন। ‘ব্ল্যাক ওয়ার’ সিনেমার জন্যেও নিজের শারীরিক গঠনে আমূল পরিবর্তন এনেছেন। মেদ ঝরিয়ে একদম ‘সিক্স প্যাক’ অ্যাবসে ধরা দিয়েছেন তিনি।শুক্রবার সন্ধ্যার শোতে রাজধানীর মধুমিতা সিনেমা হলে নিজের অভিনীত ছবি ‘ব্ল্যাক ওয়ার’ দেখতে এসে ভক্তদের আবদার মেটালেন শুভ। জামা উঁচিয়ে ‘সিক্স প্যাক’ দেখালেন ভক্তদের। সঙ্গে অনুরোধও করলেন সবাই যেন হলে এসে সিনেমাটি দেখেন।ADVERTISEMENTনিজের প্রস্তুতি বিষয়ে শুভ জানান, তিনি সিনেমাটির জন্য নয় মাস কঠোর পরিশ্রম করেছেন। পাশাপাশি সিনেমার শুটিংয়ে অনেক সময় আহতও হতে হয়েছে তাকে। এছাড়া নিজেদের প্রচুর সীমাবদ্ধতার মধ্যে কাজ করতে হয়, তাই বাইরের দেশের বড় বাজেটের সিনেমার সঙ্গে ঢালিউডকে তুলনা না করতেও অনুরোধ করেন এই নায়ক।তিনি বলেন, ‘আপনারা হলে আসবেন, ছারপোকার কামড় খাবেন। মনে রাখবেন, ছারপোকার কামড়ের দাগ মুছে যাবে। কিন্তু সিনেমা করতে গিয়ে আমার শরীরে যত ইনজুরি হয়েছে, সেগুলো সারাজীবন আমাকে ভুগতে হবে। এইটুকু কষ্টের জন্য হলেও সিনেমা দেখতে আসবেন। শুধু দেশের বাইরের কাজের সঙ্গে তুলনা করবেন না। কারণ তাদের মতো আমাদের সুযোগ-সুবিধা নেই। আমাদের দেশের সিনেমা হিসেবে কেমন হয়েছে, চেষ্টাটা করতে পেরেছি কিনা, সেটুকু মূল্যায়ন করবেন।’প্রসঙ্গত, শুক্রবার (১৩ জানুয়ারি) দেশের ৪৪ সিনেমা হলে মুক্তি পেয়েছে ‘ব্ল্যাক ওয়ার’। এতে আরিফিন শুভ ছাড়াও বিভিন্ন গুরুত্বপূর্ণ চরিত্রে অভিনয় করেছেন জান্নাতুল ফেরদৌস ঐশী, তাসকিন রহমান, সুমিত সেনগুপ্ত, মিশা সওদাগর, ফজলুর রহমান বাবু, মনোজ প্রামাণিক, শতাব্দী ওয়াদুদ, শহীদুজ্জামান সেলিম, হাসান ইমাম, লায়লা ইমাম, ইরেশ যাকের, মাজনুন মিজান, সুদীপ বিশ্বাস প্রমুখ। কপ ক্রিয়েশনের প্রযোজনায় ছবিটি যৌথভাবে পরিচালনা করেছেন সানী সানোয়ার ও ফয়সাল আহমেদ।', NULL, 'arifin-shuvoojpg-six-pack-202301141718041673728966.jpg', NULL, 'বিনোদন', 'No', '2023-01-15', '2023-01-15', '02:41AM', NULL, 1, NULL, NULL, '2023-01-15 02:42:45am', NULL, NULL, 'ঢাকা', '', NULL, 'আরিফ হোসেন', NULL, '1673728860', 'Noman Abdullah'),
(41, '', 'No', 'No', 'প্রথম দিন ‘পাঠান’ দেখবে শাহরুখের ৫০ হাজার ভক্ত!', NULL, 'বলিউড বাদশাহ শাহরুখ খান ৫ বছর পর আবারও বড় পর্দায় হাজির হচ্ছেন। আগামী ২৫ জানুয়ারি মুক্তি পাচ্ছে তার নতুন সিনেমা ‘পাঠান’। সিনেমাটি নিয়ে শাহরুখ ভক্তদের রয়েছে তুমুল আগ্রহ। এসআরকে ফ্যানক্লাবের পক্ষ থেকে ভারত জুড়ে ৫০ হাজার ভক্তের জন্য সিনেমাটির ফার্স্ট ডে ফার্স্ট শো-র আয়োজনের ঘোষণা এসেছে।ফ্যানক্লাব এসআরকে ইউনিভার্সের সহ-প্রতিষ্ঠাতা যশ পারিয়ানি পিঙ্কভিলাকে বিষয়টি নিশ্চিত করেছেন। তিনি জানান, তারা ভারতের ২০০টিরও বেশি শহরে ‘পাঠান’র শোয়ের আয়োজন করবে। শুধুমাত্র এই শো থেকেই ন্যূনতম ১ কোটি টাকার বুকিং আশা করা হচ্ছে। যার ভেতর মুম্বাইতে প্রথম দিনে ৭ থেকে ৮টি এবং দিল্লিতে ৬টি ফার্স্ট ডে ফার্স্ট শো-র আয়োজন করা হয়েছে।ADVERTISEMENTএকইভাবে দেশের অন্যান্য শহরেও একাধিক শো-র আয়োজন করা হচ্ছে। তবে এই উদযাপন শুধুমাত্র ‘পাঠান’ মুক্তির প্রথম দিনেই হবে না, চলবে প্রজাতন্ত্র দিবসের সপ্তাহন্তর অবধি।যশ পারিয়ানি আরও জানান, ‘আমরা পাঠানের জন্য বিশেষ সামগ্রীও বিতরণ করব। বিশেষ কাট আউট আর ঢোল। আমার ধারণা এসআরকে-র সিনেমাগুলোকে উৎসবের মতো উদযাপন করা হয়। পাঠানের ক্ষেত্রেও তার ব্যতিক্রম হবে না।’এদিকে, শুক্রবার দুবাইয়ে আন্তর্জাতিক লিগ টি-টোয়েন্টির উদ্বোধনী অনুষ্ঠানে উপস্থিত হয়েছিলেন শাহরুখ। সেখানে ‘পাঠান’ থেকে তার আইকনিক সংলাপও বলেছেন অভিনেতা। জানা গেছে, শাহরুখের দুবাই থাকাকালীন শনিবার (১৪ জানুয়ারি) আইকনিক বুর্জ খলিফাতে ‘পাঠান’র ট্রেলারও প্রদর্শিত হবে।', NULL, 'pathan-cover-202301141826331673729043.jpg', '1', 'বিনোদন', 'No', '2023-01-15', '2023-01-15', '02:43AM', NULL, 1, NULL, NULL, '2023-01-15 02:44:02am', NULL, NULL, 'ঢাকা', '', NULL, 'আরিফ হোসেন', NULL, '1673728980', 'Noman Abdullah'),
(42, '', 'No', 'No', 'বিএসএমএমইউয়ে ৬ রোগীর চোখে সফল কর্নিয়া প্রতিস্থাপন ', NULL, 'বঙ্গবন্ধু শেখ মুজিব মেডিকেল বিশ্ববিদ্যালয়ে (বিএসএমএমইউ) ৬ জন রোগীর চোখে সফল কর্নিয়া প্রতিস্থাপন করা হয়েছে। বৃহস্পতিবার (১২ জানুয়ারি) বিশ্ববিদ্যালয়ের চক্ষু বিজ্ঞান বিভাগ ও কমিউনিটি অফথালমোলজী বিভাগের উদ্যোগে এসব রোগীর চোখে কর্নিয়া প্রতিস্থান করা হয়। প্রতিস্থাপন করেন চক্ষু বিশেষজ্ঞ সহযোগী অধ্যাপক ডা. মোহাম্মদ শীষ রহমান এবং সহকারী অধ্যাপক ডা. রাজশ্রী দাশ।শনিবার (১৪ জানুয়ারি) দুপুরে বিশ্ববিদ্যালয়ের চক্ষু বিভাগে উপাচার্য অধ্যাপক ডা. মো. শারফুদ্দিন আহমেদ নিজে এসব রোগীদের চক্ষু পরীক্ষা করেন। পরীক্ষা নিরীক্ষায় দেখা যায় সব রোগীরই চোখ ভালো আছে এবং কর্নিয়া প্রতিস্থাপন সফলভাবে সম্পন্ন হয়েছে।ADVERTISEMENTজানা গেছে, প্রতিস্থাপন করা এসব কর্নিয়া সংগ্রহে নেপালের তিলগঙ্গা আই ইনিস্টিটিউট চক্ষু ব্যাংক ও নেপালী চিকিৎসকগণ সহায়তা করেন।কর্নিয়া প্রতিস্থাপন প্রসঙ্গে শারফুদ্দিন আহমেদ বলেন, কর্নিয়া দানের মাধ্যমে মানুষের অন্ধত্ব দূর করা সম্ভব। কর্নিয়া দান করে মৃত্যুর পরেও অন্যের চোখের দৃষ্টি হয়ে বেঁচে থাকুন। এটি একটি মহতী সুযোগ। কর্নিয়া দান একটি সহজ প্রক্রিয়া এবং এর মাধ্যমে মুখম-লের কোনো বিকৃতি হয় না।&nbsp;তিনি বলেন, কর্নিয়ার অভাবে অন্ধত্ব দূরীকরণ কার্যক্রম পুরোপুরি বাস্তবায়ন করা যাচ্ছে না। কর্নিয়া দানে জনসচেতনা বৃদ্ধিতে গণমাধ্যম বিরাট ভূমিকা রাখতে পারেন। এজন্য আমি গণমাধ্যমকর্মীদের এগিয়ে আসার আহ্বান জানাই। যাতে করে দেশবাসী কর্নিয়া দানে উৎসাহিত হয় এবং অন্ধত্ব দূরীকরণ কার্যক্রম সফল হয়।', NULL, 'bsmmu-202301141532241673729117.jpg', NULL, 'স্বাস্থ্য', 'No', '2023-01-15', '2023-01-15', '02:44AM', NULL, 1, NULL, NULL, '2023-01-15 02:45:17am', NULL, NULL, '', NULL, NULL, 'আরিফ হোসেন', NULL, '1673729040', 'Noman Abdullah'),
(43, '', 'No', 'No', 'দেশে প্রথম দাগহীন থাইরয়েড সার্জারি করলেন ডা. মাহবুব', NULL, 'দেশে প্রথম দাগবিহীন এন্ডোসকপি থাইরয়েড সার্জারি করেছেন রাজধানীর শহীদ সোহরাওয়ার্দী মেডিকেল কলেজ হাসপাতালের নাক কান গলা বিভাগের অধ্যাপক ডা. মাহবুব আলম। এ অস্ত্রোপচারের সার্বিক তত্ত্বাবধানে ছিলেন হাসপাতালটির আরেক অধ্যাপক ডা. এম এ মতিন।সংশ্লিষ্টরা জানান, সাধারণ থাইরয়েড সার্জারি করলে ঘাড়ের সামনের দিকে ৪-৬ সেন্টিমিটার দাগ থাকে। তবে এই পদ্ধতির মাধ্যমে অস্ত্রোপচারে কোনো দাগ থাকবে না। ভেস্টিবুলার (ঠোঁটের নিচের অংশ) কেটে এ অস্ত্রোপচার করা হয়। এ পদ্ধতির মাধ্যমে ৮ সেন্টিমিটার পর্যন্ত আকৃতির থাইরয়েড টিউমার অপসারণ করা সম্ভব। অপারেশন-পরবর্তী জটিলতা ও ঝুঁকি কম এবং কণ্ঠস্বরও ভালো থাকে।ADVERTISEMENTএ বিষয়ে অধ্যাপক ডা. মাহবুব আলম বলেন, এই দাগহীন অস্ত্রোপচারের কৌশল বিশ্বের বিভিন্ন দেশে জনপ্রিয় হয়ে উঠেছে। এ পদ্ধতিতে অস্ত্রোপচার হলে তিন মাসের মধ্যে দাগ সম্পূর্ণভাবে মিলিয়ে যায়। সিঙ্গাপুর, যুক্তরাষ্ট্র, থাইল্যান্ড, কোরিয়া, চীনসহ উন্নত অন্যান্য রাষ্ট্রে এ অপারেশন নিয়মিত হলেও বাংলাদেশে এবারই প্রথম করা হলো। এ পদ্ধতিতে এরই মধ্যে ছয় জনের অস্ত্রোপচার করা হয়েছে। তাদের সবাই সুস্থ রয়েছেন বলে জানান ডা. মাহবুব।গলার সামনের দিকে প্রজাপতি আকৃতির গ্রন্থিটির নাম থাইরয়েড। মানুষের বৃদ্ধি, বিকাশ, শারীরবৃত্তিক আর বিপাকীয় নানা ক্রিয়া-প্রক্রিয়া সাধন করার জন্য এই গ্রন্থি থেকে নিঃসৃত থাইরয়েড হরমোন গুরুত্বপূর্ণ ভূমিকা পালন করে। বর্তমানে থাইরয়েড গ্রন্থির নানা সমস্যা বিশ্বে অন্যতম হরমোনজনিত সমস্যা হিসেবে চিহ্নিত। হরমোনজনিত রোগের ক্ষেত্রে ডায়াবেটিসের পরই এর অবস্থান। মূলত নারীরাই এই সমস্যায় বেশি ভুগে থাকেন।', NULL, 'dr-f-202301131818111673729188.jpg', NULL, 'স্বাস্থ্য', 'No', '2023-01-15', '2023-01-15', '02:45AM', NULL, 1, NULL, NULL, '2023-01-15 02:46:27am', NULL, NULL, '', NULL, NULL, 'আরিফ হোসেন', NULL, '1673729100', 'Noman Abdullah'),
(44, '', 'No', 'No', 'ডেঙ্গু আক্রান্ত হয়ে হাসপাতালে ভর্তি ১০, একজনের মৃত্যু', NULL, 'দেশে গত ২৪ ঘণ্টায় নতুন করে ডেঙ্গু শনাক্ত হয়ে আরও ১০ জন হাসপাতালে ভর্তি হয়েছেন। এর মধ্যে ঢাকায় চার জন ও ঢাকার বাইরে বিভিন্ন হাসপাতালে ছয় জন হাসপাতালে ভর্তি হয়েছেন। এ সময়ে ডেঙ্গুতে একজনের মৃত্যু হয়েছে।শুক্রবার (১৩ জানুয়ারি) স্বাস্থ্য অধিদপ্তরের হেলথ ইমার্জেন্সি অপারেশন সেন্টার ও কন্ট্রোল রুম থেকে পাঠানো এক সংবাদ বিজ্ঞপ্তিতে এ তথ্য জানানো হয়।ADVERTISEMENTএতে বলা হয়, বর্তমানে দেশের বিভিন্ন সরকারি ও বেসরকারি হাসপাতালে মোট ১২৭ জন ডেঙ্গু রোগী চিকিৎসাধীন আছেন। ঢাকার ৫৩টি সরকারি ও বেসরকারি হাসপাতালে বর্তমানে ৫৫ জন এবং অন্যান্য বিভাগে ৭২ জন ডেঙ্গু রোগী ভর্তি রয়েছেন।চলতি বছর ডেঙ্গু আক্রান্ত হয়ে সারাদেশে এখন পর্যন্ত ৩৭০ জন রোগী হাসপাতালে ভর্তি হয়েছেন। এর মধ্যে ঢাকায় ১৭৭ জন এবং ঢাকার বাইরে ১৯৩ জন চিকিৎসা নেন।অন্যদিকে, চিকিৎসা শেষে হাসপাতাল থেকে সুস্থ হয়ে বাসায় ফিরেছেন ২৪১ জন। এর মধ্যে ঢাকায় ১২২ ও ঢাকার বাইরে বিভিন্ন স্থানে ১১৯ জন সুস্থ হয়ে বাড়ি ফিরেছেন।', NULL, 'dengue-202301131954091673729312.jpg', NULL, 'স্বাস্থ্য', 'No', '2023-01-15', '2023-01-15', '02:46AM', NULL, 1, NULL, NULL, '2023-01-15 02:48:31am', NULL, NULL, '', NULL, NULL, 'আরিফ হোসেন', NULL, '1673729160', 'Noman Abdullah'),
(45, '', 'Yes', 'No', '১০ লাখ টাকার টুর্নামেন্ট জিতল সেন্ট জোসেফ স্কুল', NULL, 'বসুন্ধরা আন্তর্জাতিক কনভেনশন সেন্টারে ঢোকার মুখেই বিশাল আকারের বিলবোর্ড বসানো। একপাশের বোর্ডে বিশ্বখ্যাত দাবাড়ু গ্র্যান্ডমাস্টার ববি ফিশার, জুডিত পোলগার, গ্যারি কাসপারভ, বিশ্বনাথন আনন্দের ছবি। অন্য পাশে বাংলাদেশের গ্র্যান্ডমাস্টার নিয়াজ মোরশেদ, জিয়াউর রহমান, রিফাত বিন সাত্তারদের ছবি। ভেতরের বড় হলরুমে শেষ হয়েছে মার্কস অ্যাকটিভ স্কুল চেস চ্যাম্পিয়নশিপ। ‘হয়ে ওঠো আগামীর গ্র্যান্ডমাস্টার’—স্লোগানে এই স্কুল টুর্নামেন্টের আয়োজক দাবা ফেডারেশন।  স্কুলভিত্তিক দলগত এই দাবা প্রতিযোগিতা শুরু হয়েছিল গত আগস্টে। প্রায় পাঁচ মাস ধরে চলা প্রতিযোগিতার গ্র্যান্ড ফাইনাল হয়ে গেল আজ বসুন্ধরা আন্তর্জাতিক কনভেনশন সেন্টারে। ফাইনালে উত্তরা ডিপিএস এসটিএস স্কুলকে হারিয়ে চ্যাম্পিয়ন হয়েছে সেন্ট জোসেফ উচ্চমাধ্যমিক স্কুল।ফাইনাল হয়েছে ফাইনালের মতোই। সাড়ে চার ঘণ্টার রোমাঞ্চকর ফাইনালে চার বোর্ডেই হয়েছে হাড্ডাহাড্ডি লড়াই। প্রথমে ২-২ গেম পয়েন্টে ড্র করে দুই দল। এরপর টাইব্রেকারে প্রতিটি স্কুল খেলেছে ১০ মিনিট ৫ সেকেন্ডের র‌্যাপিড দাবা। শেষ পর্যন্ত জয়ের হাসি হেসেছে সেন্ট জোসেফের খুদে দাবাড়ুরা।ট্রফির পাশাপাশি টুর্নামেন্টের চ্যাম্পিয়ন সেন্ট জোসেফ স্কুল পেয়েছে ১০ লাখ টাকা। রানার্সআপ স্কুল পেয়েছে ৫ লাখ টাকা। সারা দেশের মোট ২০৬২টি স্কুল অংশ নেয় মার্কস অ্যাকটিভ স্কুল চেস চ্যাম্পিয়নশিপে। প্রতিটি দলে খেলেছে ছয়জন করে দাবাড়ু। ৫৩টি জেলার প্রাথমিক পর্বের চ্যাম্পিয়ন দলগুলো সরাসরি সুযোগ পেয়েছে বিভাগীয় পর্যায়ে। বাকি ১১টি জেলাকে ভাগ করা হয় ১৭টি অঞ্চলে। এই ১৭ অঞ্চলের খেলা হয়েছে হোম অ্যান্ড অ্যাওয়ে পদ্ধতিতে। হোম অ্যান্ড অ্যাওয়ে পদ্ধতিতে খেলা ১৭টি চ্যাম্পিয়ন দল সুযোগ পায় বিভাগীয় পর্যায়ে। সব মিলিয়ে বিভাগীয় পর্যায়ে খেলেছে ৭০টি স্কুল। সেখান থেকে ৮ বিভাগের সেরা ১৬টি স্কুল নিয়ে ঢাকায় হয়েছে চূড়ান্ত পর্ব। ঢাকায় আসার পর ১৬টি স্কুল ৪টি গ্রুপে ভাগ হয়ে খেলেছে। চূড়ান্ত পর্বে গ্রুপের খেলাগুলো হয়েছে রাউন্ড রবিন লিগ পদ্ধতিতে। প্রতিটি গ্রুপের চ্যাম্পিয়ন ও রানার্সআপ দল ওঠে কোয়ার্টার ফাইনালে। এরপর হয়েছে সেমিফাইনাল ও ফাইনাল। রানার্সআপ ডিপিএস স্কুলছবি: প্রথম আলোফাইনালে সেন্ট জোসেফের হয়ে অংশ নিয়েছে তাহসিন তাজওয়ার, আহনাফ রশিদ চৌধুরী, নওশান উদ্দিন, আবরার জাহিন। উত্তরা ডিপিএস স্কুলের দাবাড়ু—আইমান আহমেদ, মারজুক চৌধুরী, মোহাম্মদ ফারজান আলী ও কাজী আফসান রওনক আনান। স্কুলের ছাত্রছাত্রীদের নিয়ে বাংলাদেশে এত বড় মাপের দাবা প্রতিযোগিতার আয়োজন আগে হয়নি। টুর্নামেন্টে সাড়াও মিলছে প্রচুর। উচ্ছ্বসিত টুর্নামেন্টের প্রধান সমন্বয়ক আন্তর্জাতিক মাস্টার আবু সুফিয়ান শাকিল বলেন, ‘আমার প্রত্যাশাকেও ছাড়িয়ে গেছে এই টুর্নামেন্ট। প্রথমদিকে ভেবেছিলাম, ঢাকার বাইরের স্কুলগুলো থেকে দাবাড়ু নাও পেতে পারি। টুর্নামেন্ট করতে গিয়ে দেখি অনেক স্কুল দল গঠন করে এসেছে। এটা দেখে আমরা অবাক হয়েছি। আসলে এটাই আমরা চেয়েছিলাম।’শাকিল জানালেন, স্কুলগুলোতে দাবার সংস্কৃতি গড়ে তুলতেই এমন আয়োজন, ‘স্কুলগুলো এরপর কোচ নিয়োগ দেবে, ক্লাব করবে, দাবার চর্চা করবে। আমাদের স্লোগানই ছিল, স্কুলগুলাতে দাবার সংস্কৃতি গড়ে তোলা।’ টুর্নামেন্ট আয়োজন করতে গিয়ে চ্যালেঞ্জের মুখে পড়তে হয়েছে ফেডারেশনকে। অনেক স্কুলে কমিটি করতে হিমশিম খেতে হয়েছে। লালমনিরহাট, পঞ্চগড়, বরগুনা, পটুয়াখালীর স্কুলে কোনো দাবাড়ুই খুঁজে পাওয়া যাচ্ছিল না। পাশের জেলা থেকে দাবাড়ু এনে শেষ পর্যন্ত অনেকে জেলা দল গঠন করে।বেশির ভাগ স্কুলের দাবাড়ুরাই প্রথমবার প্রতিযোগিতামূলক টুর্নামেন্টে খেলেছে। সেখান থেকে উঠে এসেছে সম্ভাবনাময় অনেক দাবাড়ু। কক্সবাজারের মহেশখালী স্কুল কোয়ার্টার ফাইনালে ড্র করে ডিপিএস স্কুলের সঙ্গে। শেষ পর্যন্ত অবশ্য টাইব্রেকারে হেরেছে মহেশখালী। কোয়ার্টার ফাইনালে ওঠা সব দলের দাবাড়ুদের নিয়ে আবাসিক অনুশীলন ক্যাম্প করার পরিকল্পনা রয়েছে ফেডারেশনের।স্কুল দাবায় লড়ছে স্কুলের দাবাড়ুরাছবি: প্রথম আলোগ্র্যান্ডমাস্টার জিয়াউর রহমানের ছেলে তাহসিন সেন্ট জোসেফের ছাত্র। প্রথমবারের মতো স্কুল দাবা টুর্নামেন্টে চ্যাম্পিয়ন হতে পেরে খুশি তাহসিন, ‘শেষ পর্যন্ত চ্যাম্পিয়ন হতে পেরে অনেক ভালো লাগছে। আসলে আজ শুরুতে আমরা এতটা আশাবাদী ছিলাম না। শেষের দিকে অবিশ্বাস্যভাবে আমরা ভালো খেলেছি। ১০ লাখ টাকার এই টুর্নামেন্ট স্কুলের দাবাড়ুদের জন্য। এটা দেখে অনেক ছাত্রছাত্রী এবার দাবা খেলতে আগ্রহী হবে।’গ্র্যান্ডমাস্টার জিয়াউর রহমান এই টুর্নামেন্টকে দাবার বিপ্লব হিসেবেই দেখছেন, ‘এই টুর্নামেন্টের সবচেয়ে ইতিবাচক দিক হচ্ছে এখন স্কুল টুর্নামেন্ট অনেক দাবাড় অংশ নেবে। গত এক মাস ধরে সেন্ট জোসেফ ও ডিপিএস স্কুলের বাচ্চারা আমার কাছে আগ্রহ নিয়ে খেলা শিখেছে। তাদের এই আগ্রহ দেখে আমি অনুপ্রাণিত হয়েছি। এই প্রতিযোগিতার মাধ্যমে আশা করি ভবিষ্যতে অনেক দাবাড়ু উঠে আসবে।’ বাংলাদেশের বাস্তবতায় ঘটা করে কোনো টুর্নামেন্ট আয়োজন করা হলেও পরের বছর সেটা মুখ থুবড়ে পড়ে। এই টুর্নামেন্টের ধারাবাহিকতা ধরে রাখাটাই তাই বড় চ্যালেঞ্জ, বললেন শাকিল, ‘আমাদের লক্ষ্য অনেকটাই সফল হয়েছে। কিন্তু আমাদের এটা ধারাবাহিকভাবে চালাতে হবে। যদি ৫ বছর এই প্রতিযোগিতা নিয়মিত আয়োজন করতে পারি, তাহলে আমরা দাবাড়ুদের জায়গা দিতে পারব না।’', NULL, 'chess1673879745.webp', '15', 'খেলা', 'No', '2023-01-16', '2023-01-16', '08:33PM', NULL, 1, NULL, NULL, '2023-01-16 08:35:45pm', NULL, NULL, '', NULL, NULL, 'মোঃ আব্দুল্লাহ', NULL, '1673879580', 'Noman Abdullah'),
(46, '', 'No', 'No', 'আসলে কী ঘটছে ‘কুকি-চিন’ নিয়ে', NULL, 'মিজোরা যাদের কুকি-চিন বলছে, বাংলাদেশে তারা হলো বম, লুসাই, পাংখোয়া ইত্যাদি। সংখ্যায় খুব কম এসব জাতিগোষ্ঠী। বান্দরবান সদর, রুমা, রোয়াংছড়ি, বাঘাইছড়ি, বিলাইছড়ি, বরকল অঞ্চলে এদের বেশি বসবাস, যা মিয়ানমারভুক্ত চিন প্রদেশ এবং ভারতভুক্ত মিজোরাম-সংলগ্ন। বান্দরবানের কাছাকাছি মিজোরামের জিলার নাম লঙ্গৎলাই। আর চিনের অংশ পালেতওয়া টাউনশিপের মাটুপি। কাছেই আরাকানের মংডু।ইতিমধ্যে হয়তো কিছু দেরিই হলো। অনেক বেশি দেরি হলো কি না, কে জানে! তবে সশস্ত্রতায় সমৃদ্ধি মেলে কি? বরং ‘পার্টি’র সংখ্যা বাড়তে থাকলে শান্তিতে টান পড়তে বাধ্য। ঠিক একই কারণে ঘরের কথা আইজল যায়। জাতিতে জাতিতে দূরত্ব বাড়ে। পাহাড় নিয়ে কোনো তরফ থেকেই রাজনৈতিক প্রজ্ঞার ঘাটতি না হওয়া কাম্য। বিশেষ করে গত ডিসেম্বরে যুক্তরাষ্ট্রের ‘বার্মা-অ্যাক্ট’ পাস হওয়ার পর যখন মিয়ানমারের পরিস্থিতি আরও উত্তপ্ত হওয়ার আশঙ্কা করা হচ্ছে।চার ধরনের প্রশাসনিক পরিচয় নিয়েও এ অঞ্চলে রয়েছে বহু জাতিসত্তার মানুষ। বহুকাল ধরে এ রকম জাতিসত্তাগুলোর মধ্যে নৃতাত্ত্বিক বন্ধন ঘিরে নানান ভাঙা-গড়া-সংঘাত-সংঘর্ষ ছিল এবং আছে। তার মধ্যে প্রশাসনিক হস্তক্ষেপের মিশেলও যুক্ত হয় প্রতিনিয়ত। সে রকমই এক চলতি অধ্যায়ে আইজলে এক সপ্তাহ ধরে মিজোরা বাংলাদেশের কুকি-চিনদের ব্যাপারে সমব্যথী হয়ে শান্তিপূর্ণ বিক্ষোভ করছে। ঢাকায় সে খবর হয়তো সামান্যই এসে পৌঁছাল।', NULL, 'cuki1673879953.webp', NULL, 'মতামত', 'No', '2023-01-16', '2023-01-16', '08:36PM', NULL, 1, NULL, NULL, '2023-01-16 08:39:13pm', NULL, NULL, '', NULL, NULL, 'আরিফ হোসেন', NULL, '1673879760', 'Noman Abdullah'),
(47, '', 'Yes', 'No', 'মুক্তি পেল হোলি আর্টিজানের ঘটনা নিয়ে নির্মিত সিনেমা ‘ফারাজ’-এর ট্রেলার', NULL, 'ঢাকার হোলি আর্টিজানে সংগঠিত নৃশংস হামলার ঘটনা নিয়ে ‘ফারাজ’ নামে ছবি বানাচ্ছেন মুম্বাইয়ের হংসল মেহতা, আগেই জানা গিয়েছিল এ খবর। দিন কয়েক আগে জানানো হয় ছবিটি মুক্তি পাবে আগামী ৩ ফেব্রুয়ারি। আজ সোমবার দুপুরে মুক্তি পেলে সিনেমাটির ট্রেলার।মুক্তির আগেই ভারত ও বাংলাদেশে আলোচনার জন্ম দেওয়া সিনেমাটি ভারতের সিনেমা হলে ৩ ফেব্রুয়ারি মুক্তি পাচ্ছে বলে জানিয়েছে প্রযোজনা প্রতিষ্ঠান ‘টি সিরিজ’। সিনেমাটি নির্মাণ করেছেন ‘আলীগড়’, ‘ওমের্তা’, ‘শহীদ’, ‘স্ক্যাম ১৯৯২’খ্যাত পরিচালক হংসল মেহতা। ছবিটির অন্যতম প্রযোজক আরেক প্রখ্যাত নির্মাতা অনুভব সিনহা।২ মিনিট ৬ সেকেন্ডের ‘ফারাজ’ ট্রেলার দেখলেই বোঝা যায় সিনেমাটিতে হোলি আর্টিজানে সংগঠিত ঘটনার চলচ্চিত্রায়ণ করা হয়েছে।ট্রেলারের শুরুতেই পর্দায় লেখা ওঠে ১ জুলাই ২০১৬, ঢাকা, বাংলাদেশ। এরপরই দেখানো হয় রেস্তোরাঁ, যেখানে অনেক বিদেশির আনাগোনা। হঠাৎই সেখানে হাজির হন সন্ত্রাসীরা, এলোপাতাড়ি গুলি চালাতে থাকেন। তৈরি হয় ভয়াবহ পরিবেশ।সঙ্গে দেখানো হয়েছে আইনশৃঙ্খলা রক্ষাকারী বাহিনীর তৎপরতাও। প্রথমে পুলিশ, র‍্যাব পরে দেখানো হয় সেনাবাহিনীর তৎপরতাও।বাংলাদেশের ঘটনা নিয়ে সিনেমা হলেও বলিউড সিনেমাটির সংলাপ হিন্দি, পুরো ট্রেলারে বাংলা সংলাপ ছিল না।মুক্তির আগে এক বিবৃতিতে হংসল মেহতা জানান, তরুণেরা কীভাবে সহিংসতায় জড়িয়ে পড়েন, তা আবিষ্কারের চেষ্টা করেছেন সিনেমায়। সেই সঙ্গে সহিংসতার বিরুদ্ধে দাঁড়াতে অসমসাহস ও মানবতার প্রয়োজন, সে বিষয়েও আলোকপাত করা হয়েছে সিনেমায়।প্রযোজনা করছেন অনুভব সিনহা ও ভূষণ কুমার। অনুভব সিনহা বলেন, ‘ফারাজ এমন একটি গল্প, যা বলা খুব প্রয়োজন। এ বিশ্বকে নাড়িয়ে নেওয়া ঘটনাটি সুন্দর ও নিপুণভাবে তুলে ধরেছেন হংসল।’ছবিটি দিয়ে কারিনা কাপুরের চাচাতো ভাই জাহান কাপুর ও পরেশ রাওয়ালের ছেলে আদিত্য রাওয়ালের অভিষেক হচ্ছে। গত বছর বিএফআই লন্ডন ফিল্ম ফেস্টিভ্যালে সিনেমাটির প্রিমিয়ার হয়েছে।', NULL, 'mqdefault1673883210.jpg', '28', 'বিনোদন', 'No', '2023-01-16', '2023-01-16', '09:29PM', NULL, 1, NULL, NULL, '2023-01-16 09:33:30pm', NULL, NULL, '', NULL, NULL, 'মোঃ আব্দুল্লাহ', 'aNvVwGAtnLg', '1673882940', 'Noman Abdullah');

